L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "退院おめでとう！　レイチェルお姉ちゃん！"
L4_1.m_Talk_ENG = "Welcome back! Rachel!"
L4_1.m_Talk_TWN = "瑞秋姊姊，恭喜你出院！"
L4_1.m_Talk_THA = "ยินดีต้อนรับกลับมานะเรเชล"
L4_1.m_Talk_VTN = "Chào mừng trở lại! Rachel!"
L4_1.m_Talk_SCN = "恭喜你出院！雷切尔姐姐！"
L4_1.m_Talk_DEU = "Glückwunsch zu deiner Entlassung aus dem Krankenhaus, Rachel!"
L4_1.m_Talk_FRA = "Bon retour parmi nous, Rachel !"
L5_1 = {}
L5_1.m_CutScenKey_Talk = "HORIZON_ACT6_EPILOGUE2@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 3500611
L5_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L5_1.m_bWaitClick = true
