L5_1.m_Face = "UNIT_LAUGH"
L5_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L5_1.m_Pos = "C"
L5_1.m_Crash = 15
L5_1.m_Talk_KOREA = "다들 고마워! 보육원생 레이첼, 덕분에 멀쩡하게 복귀했습니다!"
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "みんなありがとう！　レイチェル・ドッズ、みんなのおかげで元気に復帰しました！"
L5_1.m_Talk_ENG = "Thank you, everyone. I'm out of the hospital and as good as new!"
L5_1.m_Talk_TWN = "謝謝大家，育幼院院生 瑞秋平安到家！"
L5_1.m_Talk_THA = "ขอบคุณนะคะทุกคน ฉันออกจากโรงพยาบาลแล้วแจ๋วเหมือนใหม่เลย!"
L5_1.m_Talk_VTN = "Cảm ơn mọi người. Tôi ra khỏi bệnh viện và khỏe như ban đầu!"
L5_1.m_Talk_SCN = "谢谢大家！孤儿院的雷切尔，多亏大家才能安然回归！"
L5_1.m_Talk_DEU = "Vielen Dank, allerseits. Dank eurer Fürsorge bin ich so gut wie neu!"
L5_1.m_Talk_FRA = "Merci, tout le monde ! Je suis enfin sortie de l'hôpital et je suis plus en forme que jamais !"
