L9_1 = {}
L9_1.m_CutScenKey_Talk = "HORIZON_ACT6_EPILOGUE2@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 3500611
L9_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "PRINCIPAL_NPC_ORPHAN_NULL"
L9_1.m_Pos = "R_M_I"
L9_1.m_Talk_KOREA = "그렇게 까불다가 죽을 고비 넘겨 놓고서는 여전하다, 이것아."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "調子に乗りすぎてとんでもない目にあったくせに、変わらないなこいつは。"
L9_1.m_Talk_ENG = "Haven't you learned anything after almost getting yourself killed?"
L9_1.m_Talk_TWN = "你再這麼調皮，到時候又樂極生悲！"
L9_1.m_Talk_THA = "หลังจากเกือบเอาตัวไปตายมานี่เธอไม่ได้เรียนรู้อะไรเลยเหรอ?"
L9_1.m_Talk_VTN = "Cháu vẫn chưa học được gì sau khi suýt chút nữa bị giết à?"
L9_1.m_Talk_SCN = "因为调皮你差点死掉，还死性不改，你这个家伙。"
L9_1.m_Talk_DEU = "Hast du nichts dazugelernt, nachdem du dich fast umgebracht hättest?"
L9_1.m_Talk_FRA = "Tu n'as donc toujours pas retenu la leçon, hein ?"
L10_1 = {}
L10_1.m_CutScenKey_Talk = "HORIZON_ACT6_EPILOGUE2@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 3500611
L10_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "PRINCIPAL_NPC_ORPHAN_NULL"
L10_1.m_Pos = "R"
L10_1.m_Talk_KOREA = "너 병원에 있을 때 그 의사 선생님한테 인사는 제대로 드렸니?"
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "入院していた時の担当の先生にはちゃんと挨拶してきたか？"
L10_1.m_Talk_ENG = "Did you even thank your doctor properly before you left?"
L10_1.m_Talk_TWN = "你在醫院時，有好好跟醫生打招呼嗎？"
L10_1.m_Talk_THA = "จะไม่ขอบคุณคุณหมอให้ดีๆ ก่อนกลับเหรอ?"
L10_1.m_Talk_VTN = "Cháu đã cảm ơn bác sĩ hẳn hoi trước khi xuất viện chưa?"
L10_1.m_Talk_SCN = "你出院的时候有向医生好好道谢吗？"
L10_1.m_Talk_DEU = "Hast du dich vor deiner Abreise auch bei deinem Arzt bedankt?"
L10_1.m_Talk_FRA = "As-tu au moins remercié le médecin convenablement avant de partir ?"
L11_1 = {}
L11_1.m_CutScenKey_Talk = "HORIZON_ACT6_EPILOGUE2@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 3500611
L11_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L11_1.m_Pos = "L"
L11_1.m_Talk_KOREA = "당연하죠. 오늘 퇴원할 때도 뵙고 왔는데요."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "もちろんです。さっき退院手続きする時も会ってきましたよ。"
L11_1.m_Talk_ENG = "Of course. I met her right before I left today."
L11_1.m_Talk_TWN = "那當然囉！今天要出院時，我也有去跟醫生打招呼好嗎！"
L11_1.m_Talk_THA = "ต้องขอบคุณสิคะ หนูเจอเธอก่อนออกวันนี้แล้ว"
L11_1.m_Talk_VTN = "Tất nhiên. Cháu đã gặp cô ấy ngay trước khi cháu đi hôm nay."
L11_1.m_Talk_SCN = "当然啦。今天出院时特意去见了一面呢。"
L11_1.m_Talk_DEU = "Natürlich. Sogar heute habe ich ihn gesehen, vor meiner Entlassung."
L11_1.m_Talk_FRA = "Bien sûr. Je suis allée la voir avant de quitter l'hôpital aujourd'hui."
