L15_1 = {}
L15_1.m_CutScenKey_Talk = "HORIZON_ACT6_EPILOGUE2@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 3500611
L15_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_LAUGH"
L15_1.m_CharStrID = "OLIVIE_COFFIN_NULL_NULL"
L15_1.m_Pos = "L"
L15_1.m_Talk_KOREA = "쾌유해서 다행이에요. 졸업한 학생들 만나러 <color=#ffd34c>우연히</color> 오지 않았더라면 큰일이었겠어요."
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "快癒してよかったです。<color=#ffd34c>偶然</color>私が卒業生に会うためにこちらに来ていなかったら、大変なことになっていたと思います。"
L15_1.m_Talk_ENG = "Thank goodness you're all better now. It's a good thing that I <color=#ffd34c>happened to swing by</color> to meet some of my former students."
L15_1.m_Talk_TWN = "恭喜你康復，要不是我<color=#ffd34c>剛好</color>來看畢業的學生，可就糟糕囉！"
L15_1.m_Talk_THA = "โล่งใจไปที อาการเธอดีขึ้นหมดแล้วนะ โชคดีจังที่ฉัน<color=#ffd34c>บังเอิญแวะมา</color>เจออดีตนักเรียนพอดี"
L15_1.m_Talk_VTN = "Ơn trời, bây giờ cháu đã tốt hơn rồi. Thật là tốt khi tôi <color=#ffd34c>tình cờ ghé qua</color> để gặp một số học sinh cũ của tôi."
L15_1.m_Talk_SCN = "你能痊愈真是太好了。如果我不是<color=#ffd34c>偶然</color>来见毕业的学生，可能就出大事了。"
L15_1.m_Talk_DEU = "Gut, dass es dir besser geht. Wie gut, dass ich <color=#ffd34c>zufällig</color> hier war, um meine ehemaligen Schüler zu sehen."
L15_1.m_Talk_FRA = "Je suis soulagée de voir que tu vas mieux. Heureusement que je passais par là <color=#ffd34c>par hasard</color> pour rencontrer certains de mes anciens élèves."
