L17_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L17_1.m_Pos = "C"
L17_1.m_Crash = 20
L17_1.m_Talk_KOREA = "아, 네! 고맙습니다, 선생님!"
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "はい！　助かりました、先生！"
L17_1.m_Talk_ENG = "Oh, yes! Thank you, ma'am!"
L17_1.m_Talk_TWN = "是！謝謝醫生！"
L17_1.m_Talk_THA = "ใช่เลยค่ะ! ขอบคุณนะคะ!"
L17_1.m_Talk_VTN = "Ồ! Cháu cảm ơn cô ạ!"
L17_1.m_Talk_SCN = "啊，是的。谢谢您，医生！"
L17_1.m_Talk_DEU = "Oh, genau! Dankeschön!"
L17_1.m_Talk_FRA = "Oh oui ! Merci beaucoup, Madame !"
