L20_1 = {}
L20_1.m_CutScenKey_Talk = "HORIZON_ACT6_EPILOGUE2@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 3500611
L20_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_IDLE"
L20_1.m_CharStrID = "OLIVIE_COFFIN_NULL_NULL"
L20_1.m_Pos = "L"
L20_1.m_Talk_KOREA = "후훗. 뭘요. 오랜만에 저도 실력을 발휘할 수 있어서 의욕이 생기던 걸요."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "フフッ、こちらこそ、私も久しぶりに実力を発揮できていい刺激になりましたよ。"
L20_1.m_Talk_ENG = "Haha. No worries. I enjoyed the chance to brush up on my skills again too."
L20_1.m_Talk_TWN = "呵呵，不用客氣，我也久違地可以這樣大展身手。"
L20_1.m_Talk_THA = "ฮ่าฮ่า ไม่ต้องคิดมากนะ ฉันชอบเวลาได้เคาะสนิมทักษะตัวเองอีกครั้ง"
L20_1.m_Talk_VTN = "Haha. Đừng lo lắng. Cô cũng rất thích có cơ hội trau dồi kỹ năng của mình."
L20_1.m_Talk_SCN = "嘻嘻。没什么。好不容易给我一次发挥实力的机会，也让我重新充满干劲了。"
L20_1.m_Talk_DEU = "Haha. Keine Ursache. Ich habe es genossen, mein Können wieder zur Schau zu stellen."
L20_1.m_Talk_FRA = "Ha ha. Ce n'est rien. J'étais ravie de pouvoir remettre la main à la pâte."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "HORIZON_ACT6_EPILOGUE2@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 3500611
L21_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "OLIVIE_COFFIN_NULL_NULL"
L21_1.m_Pos = "L"
L21_1.m_Talk_KOREA = "안 그러니, 제자야?"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "そう思わない、弟子？"
L21_1.m_Talk_ENG = "Isn't that right, my dear protege?"
L21_1.m_Talk_TWN = "助教，你說對不對？"
L21_1.m_Talk_THA = "จริงมั้ย ศิษย์เก่าที่รัก?"
L21_1.m_Talk_VTN = "Có phải vậy không, người bảo trợ thân yêu của tôi?"
L21_1.m_Talk_SCN = "你说对不对，我的助教？"
L21_1.m_Talk_DEU = "Nicht wahr?"
L21_1.m_Talk_FRA = "N'est-ce pas, ma chère apprentie ?"
L22_1 = {}
L22_1.m_CutScenKey_Talk = "HORIZON_ACT6_EPILOGUE2@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 3500611
L22_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "LEEYOONJUNG_COFFIN_NULL_NULL"
L22_1.m_Pos = "R"
L22_1.m_Crash = 10
L22_1.m_Talk_KOREA = "하, 하하……. 네……. 그러니 제가 아직까지 붙어 있죠……."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "あ、はは……はい……だから私が辞めずに残っているわけです……"
L22_1.m_Talk_ENG = "Haha... Ha... Of course… Why else would I keep sticking around…"
L22_1.m_Talk_TWN = "哈，哈哈……對……否則我怎麼會還沒離開……"
L22_1.m_Talk_THA = "ฮ่าฮ่า... ฮ่า... จริงสิคะ... ไม่อย่างนั้นฉันจะห้อยอยู่แถวนี้ทำไม..."
L22_1.m_Talk_VTN = "Haha... Ha... Tất nhiên rồi... Còn điều gì khiến tôi cứ quanh quẩn..."
L22_1.m_Talk_SCN = "哈，哈哈……是……所以我才还留在你身边……"
L22_1.m_Talk_DEU = "Haha ... Ha ... Genau ... Nur deshalb bin ich noch nicht weggerannt ..."
L22_1.m_Talk_FRA = "Ha ha... Ha... O-Oui... Sinon ça ferait longtemps que je serais partie..."
L23_1 = {}
L23_1.m_CutScenKey_Talk = "HORIZON_ACT6_EPILOGUE2@23#Talk"
L23_1.m_CutScenProcessKey = 23
