L23_1.m_Crash = 20
L23_1.m_Talk_KOREA = "으응? 뭐라고?"
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "うん？　なんか言った？"
L23_1.m_Talk_ENG = "Huh? What was that?"
L23_1.m_Talk_TWN = "嗯？你說什麼？"
L23_1.m_Talk_THA = "หืม? อะไรล่ะนั่น?"
L23_1.m_Talk_VTN = "Hử? Gì đó?"
L23_1.m_Talk_SCN = "嗯？你说什么？"
L23_1.m_Talk_DEU = "Hm? Wie bitte?"
L23_1.m_Talk_FRA = "Hum ? Qu'est-ce que tu as dis ?"
L24_1 = {}
L24_1.m_CutScenKey_Talk = "HORIZON_ACT6_EPILOGUE2@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 3500611
L24_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_SURPRISE"
L24_1.m_CharStrID = "LEEYOONJUNG_COFFIN_NULL_NULL"
L24_1.m_Pos = "R"
L24_1.m_Crash = 10
L24_1.m_Talk_KOREA = "제, 제가 무슨 소리 했나요?! 아무것도 아닙니다!"
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "わ、私何か言いましたか！？　何でもないです！"
L24_1.m_Talk_ENG = "D-Did I say something?! It's nothing!"
L24_1.m_Talk_TWN = "我…我有說什麼嗎？我什麼都沒說！"
L24_1.m_Talk_THA = "ฉะ-ฉันพูดอะไรเหรอคะ?! เปล่านะคะ!"
L24_1.m_Talk_VTN = "T-Tôi đã nói gì đó không phải ư?! Không có gì cả mà!"
L24_1.m_Talk_SCN = "我、我刚才说什么了吗？！什么都没有！"
L24_1.m_Talk_DEU = "H-habe ich etwas gesagt?! Nichts!"
L24_1.m_Talk_FRA = "J-J'ai pensé à voix haute ?! Non, rien !"
