L26_1 = {}
L26_1.m_CutScenKey_Talk = "HORIZON_ACT6_EPILOGUE2@26#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 3500611
L26_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "OLIVIE_COFFIN_NULL_NULL"
L26_1.m_Pos = "C"
L26_1.m_Talk_KOREA = "몸에 후유증은 여전할 거예요. 대표적으로 그 등의 화상."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "後遺症は残るでしょう。例えばその背中の火傷。"
L26_1.m_Talk_ENG = "You'll still suffer from various sequelae. Especially that burn on your back."
L26_1.m_Talk_TWN = "身體會留下後遺症，像是背上的燒傷。"
L26_1.m_Talk_THA = "ระบบประสาทเธอยังมีผลกระทบหลายจุดนะ โดยเฉพาะรอบไหม้บนหลังนั่น"
L26_1.m_Talk_VTN = "Cháu sẽ vẫn phải chịu nhiều di chứng khác nhau. Đặc biệt là vết bỏng trên lưng của cháu."
L26_1.m_Talk_SCN = "身体上可能会留下些后遗症。比如背上的烧伤。"
L26_1.m_Talk_DEU = "Du wirst unter verschiedenen Folgeerscheinungen leiden. Vor allem das Brennen auf dem Rücken."
L26_1.m_Talk_FRA = "Tu vas malheureusement souffrir de quelques séquelles. Je parle surtout de cette brûlure sur ton dos."
L27_1 = {}
L27_1.m_CutScenKey_Talk = "HORIZON_ACT6_EPILOGUE2@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 3500611
L27_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "OLIVIE_COFFIN_NULL_NULL"
L27_1.m_Pos = "C"
L27_1.m_Talk_KOREA = "흉터는 물론이고, 정기적으로 병원에서 진찰 받아야 해요."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "傷跡はもちろん、定期的に病院で診察を受けなければなりません。"
L27_1.m_Talk_ENG = "It'll scar for sure. And you should get it periodically checked out at the hospital."
L27_1.m_Talk_TWN = "疤是一定的，你要定期到醫院回診喔。"
L27_1.m_Talk_THA = "มันจะเป็นแผลเป็นแน่ๆ และเธอควรไปตรวจที่โรงพยาบาลเป็นระยะ"
L27_1.m_Talk_VTN = "Chắc chắn nó sẽ có sẹo. Và cháu nên kiểm tra định kỳ tại bệnh viện."
L27_1.m_Talk_SCN = "不仅会留疤，还需要定期来医院检查。"
L27_1.m_Talk_DEU = "Es wird sicher Narben geben. Und du solltest dich regelmäßig im Krankenhaus untersuchen lassen."
L27_1.m_Talk_FRA = "Elle finira par cicatriser, je n'en doute pas. Mais tu devras la faire ausculter à l'hôpital régulièrement."
L28_1 = {}
L28_1.m_CutScenKey_Talk = "HORIZON_ACT6_EPILOGUE2@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 3500611
L28_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "OLIVIE_COFFIN_NULL_NULL"
L28_1.m_Pos = "C"
L28_1.m_Talk_KOREA = "비누칠도 되도록이면 살살 하고. 아까운 미모를 잃지 않았으니 더 열심히 가꿔야죠?"
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "洗う時もできる限り優しく。幸いそのキレイな顔には傷跡が残ってないから、これからも大事にしないとですね。"
L28_1.m_Talk_ENG = "Make sure you lather the soap gently on the affected area. You were lucky enough to hang onto your beauty. You should take extra good care of it now."
L28_1.m_Talk_TWN = "搓肥皂的時候，也要盡可能動作溫柔一點，既然保住這張漂亮的臉，當然要好好對待它囉！"
L28_1.m_Talk_THA = "อย่าลืมถูฟองสบู่เบาๆ บริเวณที่มีอาการล่ะ เธอยังโชคดีนะที่ไม่เสียโฉม ตอนนี้ก็ดูแลให้ดีๆ ล่ะ"
L28_1.m_Talk_VTN = "Hãy nhớ thoa nhẹ xà phòng lên vùng da bị mụn. Cháu đủ may mắn để còn giữ lại vẻ ngoài xinh xắn đấy. Cháu nên chăm sóc nó thật tốt ngay bây giờ."
L29_1 = "洗澡也要尽量轻一些。还好没失去美貌的脸蛋，应该更加努力保养才行呢。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Seif dich beim Waschen möglichst sanft ein. Du hast deine Schönheit behalten, also kümmere dich darum."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Fais en sorte de laver la zone affectée doucement avec du savon. Tu as eu la chance de pouvoir préserver ton physique de rêve, alors prends bien soin de toi !"
L28_1.m_Talk_FRA = L29_1
