L32_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L32_1.m_Pos = "L"
L32_1.m_Crash = 10
L33_1 = "제가 보기에는 그래도 수술 겁나 잘 됐다 싶던데, 어때요?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "素人の私がみても手術はちょーうまくいったと思いますよ！　ほら、どうですか？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I thought the surgery went super well though. How does it look?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "我自己覺得手術滿順利的，你們覺得呢？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ฉันนึกว่าการผ่าตัดเรียบร้อยดีมากๆ ซะอีกนะคะ มันดูเป็นไงบ้างคะเนี่ย?"
L32_1.m_Talk_THA = L33_1
L33_1 = "Cháu nghĩ rằng cuộc phẫu thuật đã diễn ra rất tốt. Trông nó thế nào?"
L32_1.m_Talk_VTN = L33_1
L33_1 = "在我看来这场手术非常顺利，不是吗？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Aber ich finde, die OP ist supergut verlaufen. Was meint ihr?"
L32_1.m_Talk_DEU = L33_1
L33_1 = "En tout cas, je trouve que la chirurgie s'est super bien passée ! Comment vous trouvez ma cicatrice ?"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
