L33_1.m_Pos = "R"
L34_1 = 30
L33_1.m_Crash = L34_1
L34_1 = "외투 걸쳐, 이 녀석아! 다 커 갖고 애들 보는 앞에서 무슨 짓이야!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "こらこら、服を着なさい！　いい年して子どもたちの前で何をしてるんだ！"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Put your coat back on, you fool! There are kids watching!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "你這丫頭，把外套穿好！在大家面前這樣成何體統！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ใส่เสื้อเดี๋ยวนี้เลยนะ เด็กโง่นี่! เด็กๆ ดูอยู่!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Mặc áo khoác lại đi, đồ ngốc! Bọn trẻ đang nhìn đấy!"
L33_1.m_Talk_VTN = L34_1
L34_1 = "穿上外套，你这孩子！已经不是小孩子了，还敢在其他孩子面前放肆！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Zieh deinen Mantel wieder an! Hier sind Kinder, die zuschauen!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Remonte ton manteau, espèce d'idiote ! Y'a des enfants qui regardent !"
L33_1.m_Talk_FRA = L34_1
