L36_1 = "FX_CUTSCEN_NOISE_RUSTLE_02"
L35_1.m_StartFXSoundName = L36_1
L36_1 = "GIRL_NPC_HORIZON_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "언니, 이거 받아. 언니 입원해 있는 동안 우리가 산 스프레이야."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "お姉ちゃん、これあげる。お姉ちゃんが入院している間、エマたちが買ったスプレーだよ。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Here, Rachel. We bought you a can of spray paint while you were in the hospital."
L35_1.m_Talk_ENG = L36_1
L36_1 = "姊姊，這個給你，這是我們在姊姊住院時買的噴漆。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "นี่จ้ะ เรเชล ตอนเธออยู่โรงพยาบาลเราซื้อสเปรย์ไว้ให้ด้วยนะ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Đây, Rachel. Bọn em đã mua cho chị một hộp sơn xịt khi chị đang ở bệnh viện."
L35_1.m_Talk_VTN = L36_1
L36_1 = "姐姐，这个给你。是你住院的时候，我们买的喷漆。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Hier, für dich. Wir haben dir eine Dose Sprühfarbe gekauft, während du im Krankenhaus warst."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Tiens, c'est pour toi, Rachel. On a acheté une bombe de peinture pour toi pendant que tu étais à l'hôpital."
L35_1.m_Talk_FRA = L36_1
