L38_1.m_Face = "UNIT_SURPRISE"
L38_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L38_1.m_Pos = "L"
L38_1.m_Crash = 20
L39_1 = "정말? 너희들이 무슨 돈이 있어서?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "本当に？　あんたたちお金はどうやって貯めたの？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Really? How did you guys even afford this?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "真的嗎？你們哪來的錢？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "จริงเหรอ? พวกเธอไปเอาเงินมาจากไหนเนี่ย?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Có thật không? Làm sao mà các em đủ tiền mua thế?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "真的？你们哪来的钱？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Echt? Wie konntet ihr euch das nur leisten?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Vraiment ? Comment est-ce que vous avez trouvé de quoi acheter ça ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "HORIZON_ACT6_EPILOGUE2@39#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 39
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3500611
L39_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "PRINCIPAL_NPC_ORPHAN_NULL"
L39_1.m_Pos = "R"
L40_1 = "말도 마라. 그 돈 모으겠다고 얘들이 동네 들쑤시고 다녀서 혼났어."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "まったく。お金がほしいからって町中をかき回してこっちが大変だったんだ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Don't even get me started. They've been turning the entire neighborhood upside down to save up for that."
L39_1.m_Talk_ENG = L40_1
L40_1 = "別提了，他們為了存錢，翻遍整個難民區，還害我被罵！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "อย่าให้ต้องเริ่มสาธยาย พวกนั้นทำแถวที่อยู่โกลาหลไปหมดเพื่อเก็บเงินซื้อน่ะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Đừng có gây sự với bác. Bọn trẻ đã lật tung toàn bộ khu phố để tiết kiệm tiền mua nó."
L39_1.m_Talk_VTN = L40_1
L40_1 = "还用说吗。为了攒钱孩子们把社区翻了个底朝天。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Frag nicht. Sie haben die ganze Nachbarschaft auf den Kopf gestellt, um das Geld dafür zusammen zu bekommen."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Ne m'en parle même pas ! Les enfants ont mis tout le quartier sans dessus-dessous pour trouver de quoi payer cette bombe de peinture."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "HORIZON_ACT6_EPILOGUE2@40#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L40_1.m_CutScenProcessKey = 40
L40_1.m_CutScenID = 3500611
L40_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "PRINCIPAL_NPC_ORPHAN_NULL"
L40_1.m_Pos = "R"
L40_1.m_Crash = 10
L41_1 = "쥐 잡기에 폐지 모으기에……. 자경단이 나더러 요새 애들 굶기냐고 물어보더라."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "ネズミ捕りに古紙集めに……自警団から最近子どもたちにちゃんとご飯をあげてるのかと散々疑われたんだぞ。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "They caught rats, collected all the recyclables… The neighborhood watch asked me if I wasn't feeding them properly."
L40_1.m_Talk_ENG = L41_1
L41_1 = "他們就是抓老鼠，或是回收廢紙……搞到自衛隊還來問我，最近是不是讓孩子們餓肚子！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "พวกนั้นทั้งจับหนู เก็บขยะรีไซเคิลทุกชนิด... คนแถวนั้นถึงกับมาถามฉันว่าไม่ได้ให้กินข้าวเหรอ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Bọn trẻ bắt chuột, thu gom tất cả đồ tái chế… cảnh vệ khu phố hỏi bác rằng có cho chúng ăn đủ không."
L40_1.m_Talk_VTN = L41_1
L41_1 = "不仅抓老鼠，还要收集废纸……因此自卫队的人还问我是不是没给孩子们饭吃。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Sie haben Ratten gefangen, Altpapier eingesammelt ... Die Stadtwache hat mich gefragt, ob sie nichts zu essen kriegen."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Ils se sont mis à attraper les rats, à ramasser les déchets... Les Sentinelles ont même cru que je les laissais mourir de faim."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "HORIZON_ACT6_EPILOGUE2@41#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 41
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3500611
L41_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "UNIT_PRIDE"
L41_1.m_Face = L42_1
L41_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L41_1.m_Pos = "L"
L42_1 = "헤헤, 농담으로 한 소리겠죠. 이 동네에서 원장님 마음 넓은 걸 누가 모른다고."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "へへ、冗談で聞いたんだと思いますよ。この町で院長の心の広さを知らない人はいませんって。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Haha, I'm sure they were kidding. Everyone in this neighborhood knows how generous you are."
L41_1.m_Talk_ENG = L42_1
L42_1 = "嘿嘿，院長是說笑的吧？難民區裡誰不知道院長心胸廣大！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ฮ่าฮ่า หนูว่าพวกเขาล้อเล่นแหงๆ ค่ะ คนแถวนั้นก็รู้กันหมดนะคะว่าครูใจดีขนาดไหน"
L41_1.m_Talk_THA = L42_1
L42_1 = "Haha, cháu chắc rằng họ chỉ đang đùa. Mọi người trong khu phố này đều biết bác hào phóng như thế nào."
L41_1.m_Talk_VTN = L42_1
L42_1 = "嘿嘿。他们也是在开玩笑吧。我们这儿谁不知道院长宽宏大量呢。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Haha, das war sicher ein Witz. Jeder in dieser Nachbarschaft weiß, wie großzügig Sie sind."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Hé hé, c'était sûrement une blague. Tout le monde sait bien que vous êtes un homme généreux !"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "HORIZON_ACT6_EPILOGUE2@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3500611
L42_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L42_1.m_Pos = "L"
L43_1 = 30
L42_1.m_Crash = L43_1
L43_1 = "이마만 봐도 티가 확 나잖아요?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "心の広さと同じくらい広いそのおでこを見ればわかること！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "You even generously reflect the sunlight for us with your smooth, shiny head!"
L42_1.m_Talk_ENG = L43_1
L43_1 = "人家說十個禿子十個善呢！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ครูน่ะใจดีขนาดว่าสะท้อนแสงอาทิตย์ให้เราด้วยหัวล้านเลี่ยนเงาวิ้งนั่น!"
L42_1.m_Talk_THA = L43_1
L43_1 = "Bác thậm chí còn hào phóng phản chiếu ánh sáng mặt trời cho chúng cháu bằng cái đầu hói sáng bóng mà!"
L42_1.m_Talk_VTN = L43_1
L43_1 = "看发际线也能看出来，不是吗？"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Mit Ihrem glatten, glänzenden Kopf reflektieren Sie sogar großzügig das Sonnenlicht für uns!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Si généreux que vous nous baignez même de la lumière du soleil grâce à votre grand front luisant."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "HORIZON_ACT6_EPILOGUE2@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3500611
L43_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "PRINCIPAL_NPC_ORPHAN_NULL"
L43_1.m_Pos = "R"
L44_1 = "너 이 녀석아, 오늘 퇴원한 날이라 봐 주는 거야."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "こらっ！　まあでも今日は退院日だから大目に見てやる。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I'll let that slide, just for today, seeing as you just got out of the hospital."
L43_1.m_Talk_ENG = L44_1
L44_1 = "你這丫頭！看在你今天出院的份上放你一馬！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ครูจะทำเป็นไม่ได้ยินแล้วกัน แต่แค่วันนี้นะ ถือว่าเพิ่งออกจากโรงพยาบาล"
L43_1.m_Talk_THA = L44_1
L44_1 = "Ta sẽ bỏ qua, chỉ trong ngày hôm nay thôi đấy, vì cháu vừa ra khỏi bệnh viện."
L43_1.m_Talk_VTN = L44_1
L44_1 = "你这个家伙，看在今天刚出院的份上，我就放你一马。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich lasse das nur heute durchgehen, da du gerade aus dem Krankenhaus kommst."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Toi... Je vais laisser passer ça pour, cette fois. Parce que tu sors tout juste de l'hôpital."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
