L46_1 = "HORIZON_ACT6_EPILOGUE2@45#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 45
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3500611
L45_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_IDLE"
L45_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L45_1.m_Pos = "C"
L46_1 = "그런데 호라이즌은 다시 왔어요?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "ところでホライズンは？　戻ってきました？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "By the way, did Horizon come back?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "不過地平線還有回來嗎？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ว่าแต่ ฮอไรซันกลับมารึยังคะ?"
L45_1.m_Talk_THA = L46_1
L46_1 = "Nhân tiện, Horizon có quay lại không?"
L45_1.m_Talk_VTN = L46_1
L46_1 = "话说地平线回来了吗？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Übrigens ... ist Horizon zurück?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Au fait, est-ce qu'Horizon est revenue ?"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "HORIZON_ACT6_EPILOGUE2@46#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3500611
L46_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "PRINCIPAL_NPC_ORPHAN_NULL"
L46_1.m_Pos = "C"
L47_1 = 30
L46_1.m_Crash = L47_1
L47_1 = "그 망나니랑은 절대 엮이지 마! 절대로!"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "そいつとは二度と関わるな！　絶対に！"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Don't you ever get involved with that thug again! Ever!"
L46_1.m_Talk_ENG = L47_1
L47_1 = "不准你和那種不良少女有牽扯！聽到沒有！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "อย่าได้ไปยุ่งกับเด็กเกเรนั่นอีกเชี่ยวนะ! ห้ามเด็ดขาด!"
L46_1.m_Talk_THA = L47_1
L47_1 = "Đừng bao giờ dính dáng đến tên côn đồ đó nữa! Đừng bao giờ!"
L46_1.m_Talk_VTN = L47_1
L47_1 = "千万别再和那个混混来往！绝对不可以！"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Lass dich nie wieder mit diesem Schläger ein! Niemals!"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Je t'interdis d'avoir quoi que ce soit à faire avec cette vaurienne, tu m'entends ?!"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "HORIZON_ACT6_EPILOGUE2@47#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 47
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3500611
L47_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_DESPAIR"
L47_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L47_1.m_Pos = "C"
L48_1 = "왜, 왜 갑자기 성질이람."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "えー急に大声出さないでくださいよ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Woah, why the sudden outburst?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "為什麼？幹嘛突然發火？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "เหวอ ทำไมอยู่ๆ ก็เดือดคะเนี่ย?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Woah, tại sao đột nhiên bác lại xửng cồ lên thế?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "为什么，你干嘛突然发火啊。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "W-warum der plötzliche Wutausbruch?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Eh bien ! Pas la peine de s'énerver."
L47_1.m_Talk_FRA = L48_1
