L51_1 = "HORIZON_ACT6_EPILOGUE2@50#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 50
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3500611
L50_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "PRINCIPAL_NPC_ORPHAN_NULL"
L50_1.m_Pos = "R"
L51_1 = "왜긴 왜야? TV에 대문짝만 하게 재판 받는 모습이 나왔으니까 그렇지!"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "知らないのか？　テレビで裁判を受ける姿が連日報道されていたんだぞ！"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Why else? They've been showing her trial all over TV!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "什麼為什麼？因為我在電視上看到他受審的畫面！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "จะอะไรซะอีก? พิธีพิจารณาคดีเธอออกทีวีทุกช่องเลย!"
L50_1.m_Talk_THA = L51_1
L51_1 = "Còn lý do nào khác? Họ đã chiếu nó trên TV!"
L50_1.m_Talk_VTN = L51_1
L51_1 = "还用问为什么吗？当然是因为在电视上看到了她被审判的视频！"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Warum wohl? Sie haben ihren Gerichtsprozess als Extrameldung im Fernsehen übertragen!"
L50_1.m_Talk_DEU = L51_1
L51_1 = "J'ai toutes les raisons de m'énerver. Son procès a été diffusé en boucle sur toutes les chaînes de télé."
L50_1.m_Talk_FRA = L51_1
