L1_1.m_CharStrID = "PRINCIPAL_NPC_ORPHAN_NULL"
L1_1.m_Pos = "R"
L1_1.m_Crash = 10
L2_1 = "국제적으로 폭행 범죄를 일으키고 다니는 미치광이가 우리 보육원에 들어왔었다니, 어유! 소름 끼쳐!"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "国際的な暴行犯罪を起こすイカれた奴がうちの施設にいたなんて、鳥肌が立つくらいだよ！"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I can't believe we let an international terrorist in to our orphanage! It still gives me chills to think about it!"
L1_1.m_Talk_ENG = L2_1
L2_1 = "那種國際罪犯竟然曾經出現在我們育幼院！想到我就覺得可怕！"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ไม่อยากเชื่อเลยว่าครูปล่อยให้ผู้ก่อการร้ายข้ามชาตินั่นเข้ามาในบ้านเด็กกำพร้าของเรา! คิดแล้วยังขนลุกไม่หาย!"
L1_1.m_Talk_THA = L2_1
L2_1 = "Ta không thể tin được là chúng ta lại để một tên khủng bố quốc tế vào trại trẻ mồ côi của chúng ta! Nó vẫn khiến ta ớn lạnh khi nghĩ đến đấy!"
L1_1.m_Talk_VTN = L2_1
L2_1 = "谁能想到，我们孤儿院里来了个国际暴力犯罪份子，哎！想想都让人头皮发麻！"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Unfassbar, dass wir einen internationalen Terroristen in unser Waisenhaus gelassen haben! Ich bekomme Gänsehaut, wenn ich daran denke!"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Je n'arrive pas à croire qu'on ai laissé entrer un terroriste international dans notre orphelinat ! J'en ai des frissons dans le dos rien que d'y penser !"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "HORIZON_ACT6_EPILOGUE2@52#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 52
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 3500611
L2_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L2_1.m_Pos = "L"
L3_1 = "맞을 만한 짓을 했으니까 맞았겠지, 뭘."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "相手が殴られるようなことをしたから殴られたんでしょ。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "I'm sure they probably deserved it."
L2_1.m_Talk_ENG = L3_1
L3_1 = "可是做壞事不是本來就活該被打嗎？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ฉันแน่ใจว่าพวกนั้นสมควรโดนแล้วนะคะ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Cháu chắc chắn là vì chúng đáng bị thế."
L2_1.m_Talk_VTN = L3_1
L3_1 = "被她打的人肯定是因为罪有应得，哼。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Ich bin sicher, dass sie es verdient hatten."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Je suis persuadée qu'elle avait une bonne raison de faire ce qu'elle a fait."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "HORIZON_ACT6_EPILOGUE2@53#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3500611
L3_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "PRINCIPAL_NPC_ORPHAN_NULL"
L3_1.m_Pos = "R"
L3_1.m_Crash = 20
L4_1 = "어허! 레이첼 너! 그런 말 하고 다니면 혼나!"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "こら、レイチェル！　そんなこと言うんじゃない！"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Shush! Rachel! You'll get yourself into trouble if you say stuff like that out loud!"
L3_1.m_Talk_ENG = L4_1
L4_1 = "閉嘴！瑞秋！你再說這種話院長會生氣喔！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ชู่ว! เรเชล! พูดแบบนั้นดังๆ จะเดือดร้อนเอานะ!"
L3_1.m_Talk_THA = L4_1
L4_1 = "Shush! Rachel! Cháu sẽ tự gây rắc rối nếu cháu dám nói to những điều như vậy!"
L3_1.m_Talk_VTN = L4_1
L4_1 = "嗯？雷切尔！如果你敢在外边说这种话，小心我收拾你！"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Hey! Rachel! Du handelst dir noch Ärger ein, wenn du so etwas laut sagst!"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Chut, Rachel ! Tu vas t'attirer des ennuis si tu cries ça sur tous les toits !"
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "HORIZON_ACT6_EPILOGUE2@54#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 54
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3500611
L4_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "PRINCIPAL_NPC_ORPHAN_NULL"
L4_1.m_Pos = "R"
L4_1.m_Crash = 5
L5_1 = "그러고 보니 요즘 뉴스에 이상하게 말이 없던데……. 너 혹시나 마주치지 않게 조심해야 돼."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "しかし最近はニュースに出てこないな……二度と絡まれないように気を付けるんだぞ。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Strangely enough though, they stopped talking about her on the news recently… Be careful you don't run into her again."
L4_1.m_Talk_ENG = L5_1
L5_1 = "不過話說回來，最近好像沒有她的報導……你自己要小心點不要遇到她！"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แต่ก็แปลนะ อยู่ๆ ช่วงนี้ข่าวก็เลิกพูดเรื่องเธอ... ระวังอย่าไปเจอเธออีกแล้วกัน"
L4_1.m_Talk_THA = L5_1
L5_1 = "Tuy nhiên, thật kỳ lạ, gần đây họ đã ngừng nói về cô ấy trên tin tức… Hãy cẩn thận, đừng gặp lại cô ấy một lần nữa."
L4_1.m_Talk_VTN = L5_1
L5_1 = "说起来，好像最近的新闻上没有关于她的报道……你要小心别遇到她。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Seltsamerweise wird sie in den Nachrichten nicht mehr erwähnt ... Pass auf, dass du ihr nicht noch einmal über den Weg läufst."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Mais bizarrement, ils ont arrêté de parler d'elle en ce moment... Alors fais bien attention de na pas la croiser à nouveau."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "HORIZON_ACT6_EPILOGUE2@55#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 55
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3500611
L5_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L5_1.m_Pos = "L"
L6_1 = "어휴. 오자마자 잔소리."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "はあ、退院早々小言ばかり。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Ugh. You really gotta nag me the moment I get back?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "真的是，一來就長篇大論。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "เอ่อ ใจคอจะดุกันทันทีที่ฉันกลับมาเลยเหรอคะ?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Ugh. Bác thực sự phải cằn nhằn cháu ngay khi cháu vừa về sao?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "哎呀。别刚见面就这么啰嗦了。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Pah. Kaum bin ich wieder da, nörgeln Sie wieder."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Pfiou. Vous êtes vraiment obligé de me rouspéter à peine arrivée ?"
L5_1.m_Talk_FRA = L6_1
