L7_1.m_Pos = "C"
L7_1.m_Crash = 20
L8_1 = "어, 어디 가는 거니? 레이첼!"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "ど、どこに行くんだ、レイチェル！？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "W-where are you going? Rachel!"
L7_1.m_Talk_ENG = L8_1
L8_1 = "喂，你去哪？瑞秋！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ธะ-เธอจะไปไหนน่ะ? เรเชล!"
L7_1.m_Talk_THA = L8_1
L8_1 = "C-cháu đi đâu vậy? Rachel!"
L7_1.m_Talk_VTN = L8_1
L8_1 = "你、你去哪？雷切尔！"
L7_1.m_Talk_SCN = L8_1
L8_1 = "W-wohin gehst du? Rachel!"
L7_1.m_Talk_DEU = L8_1
L8_1 = "O-Où est-ce que tu vas, Rachel ? Rachel !"
L7_1.m_Talk_FRA = L8_1
