L9_1 = "HORIZON_ACT6_EPILOGUE2@58#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 58
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3500611
L8_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_LAUGH"
L8_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L8_1.m_Pos = "C"
L8_1.m_Crash = 15
L9_1 = "선물 받은 스프레이 써 봐야죠! 멀리 안 나가요!"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "プレゼントでもらったスプレーを試してきますね！　遠くまで行かないから安心して！"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I want to try out this new spray paint they got me! I'm not going far!"
L8_1.m_Talk_ENG = L9_1
L9_1 = "拿到禮物當然就要用囉～我在附近而已！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "หนูอยากลองสีสเปรย์ใหม่ที่พวกนั้นซื้อมาให้น่ะค่ะ! ไปไม่ไกลหรอกนะคะ!"
L8_1.m_Talk_THA = L9_1
L9_1 = "Cháu muốn thử loại sơn phun mới này mà bọn trẻ đã mua cho cháu! Cháu sẽ không đi xa đâu!"
L8_1.m_Talk_VTN = L9_1
L9_1 = "当然是去试试刚收到的喷漆啦！不会走远的！"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ich muss die neue Sprühfarbe ausprobieren, die ich geschenkt bekommen habe! Ich gehe nicht weit weg!"
L8_1.m_Talk_DEU = L9_1
L9_1 = "J'ai envie d'essayer cette nouvelle bombe de peinture que les enfants m'ont offerte ! Je ne vais pas loin !"
L8_1.m_Talk_FRA = L9_1
