L12_1.m_Pos = "L"
L12_1.m_Crash = 15
L13_1 = "오, 레이첼! 멀쩡하네?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "おお、レイチェル！　元気そうじゃないか！"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Oh, Rachel! You look perfectly fine!"
L12_1.m_Talk_ENG = L13_1
L13_1 = "喔，是瑞秋！你沒事啦？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "โอ้ เรเชล! เธอดูไม่เป็นอะไรเลยนะนี่!"
L12_1.m_Talk_THA = L13_1
L13_1 = "Ôi, Rachel! Trông cô hoàn toàn ổn đấy!"
L12_1.m_Talk_VTN = L13_1
L13_1 = "噢，雷切尔！你没事了？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ach, Rachel! Du siehst vollkommen in Ordnung aus!"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Oh, Rachel ! T'as l'air d'aller bien !"
L12_1.m_Talk_FRA = L13_1
