L15_1 = "UNIT_PRIDE"
L14_1.m_Face = L15_1
L14_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L14_1.m_Pos = "C"
L14_1.m_Crash = 10
L15_1 = "의사 잘 만난 덕분이지. 요즘 좀 어때?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "腕のいいお医者さんのおかげだよ。最近どう？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Yeah, I had a good doctor. How's everything these days?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "幸運遇到好醫生的嘛～大家最近好嗎？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ค่า ได้หมอดีน่ะ ตอนนี้อะไรๆ เป็นยังไงบ้างคะเนี่ย?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Yeah, tôi có một bác sĩ giỏi. Dạo này mọi thứ thế nào?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "因为遇到了一位好医生。最近你们怎么样？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ja, ich hatte einen guten Arzt. Wie läuft es so bei euch?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Oui, j'ai eu un médecin avec des doigts de fée. Comment ça va en ce moment ?"
L14_1.m_Talk_FRA = L15_1
