L18_1 = "MEMBER2_NPC_MILITIA_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "R"
L18_1 = "그게 말이야, 교관님께서 네 수술 잘 끝났다는 소식 듣자마자 떠나셨어."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "それがな、教官がお前の手術が無事に終わったと聞いた後、去っていったんだ。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Oh, well… The Instructor left the moment he heard your surgery went well."
L17_1.m_Talk_ENG = L18_1
L18_1 = "這個嘛，教官一聽說你的手術順利結束後，就立刻離開了。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "อ่อ คือ... พอรู้ว่าการผ่าตัดเป็นไปด้วยดีครูเขาก็ไปเลย"
L17_1.m_Talk_THA = L18_1
L18_1 = "Ồ, chà… Sĩ Quan Huấn Luyện đã rời đi ngay khi nghe tin cuộc phẫu thuật của cô diễn ra tốt đẹp."
L17_1.m_Talk_VTN = L18_1
L18_1 = "那个……教官听到你手术顺利的消息后就离开了。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Oh, na ja ... Der Ausbilder reiste in dem Moment ab, als er hörte, dass deine Operation gut verlaufen ist."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Oh, eh bien... L'instructeur est parti dès qu'il a entendu que ta chirurgie s'était bien déroulée."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
