L20_1 = 30
L19_1.m_Crash = L20_1
L20_1 = "뭐? 왜?! 매점에서 술 빼돌리다가 들켰대?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "え？　なんで？　コンビニの酒を転売でもしてバレたの？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "What? Why? Did he get caught stealing booze from the convenience store?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "什麼？為什麼？被他發現我偷商店的酒嗎？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "หา? ทำไมละคะ? เขาโดนจับเพราะขโมยเหล้าจากร้านสะดวกซื้อเหรอ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Gì? Tại sao? Anh ta có bị bắt quả tang ăn trộm rượu từ cửa hàng tiện lợi không?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "什么？为什么？他在便利店偷酒喝被发现了吗？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Was? Wieso denn? Hat er Alkohol aus dem Laden gestohlen und wurde dabei erwischt?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Hein ? Pourquoi ? Ne me dis pas qu'on l'a encore attrapé la main de le sac, en train d'essayer de voler de l'alcool à la supérette ?"
L19_1.m_Talk_FRA = L20_1
