L23_1 = "MEMBER_NPC_MILITIA_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "L"
L23_1 = "으음, 글쎄. 우리도 이유는 못 들었어."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "さあな。俺らも理由は聞けてない。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Hmm, I'm not sure. We didn't exactly hear why either."
L22_1.m_Talk_ENG = L23_1
L23_1 = "嗯，不知道，我們也沒聽說原因。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "อืมมม ผมก็ไม่รู้สิ เราก็ไม่รู้เหมือนกันว่าทำไม"
L22_1.m_Talk_THA = L23_1
L23_1 = "Hmm, tôi không chắc. Chúng tôi cũng không biết chính xác lý do tại sao."
L22_1.m_Talk_VTN = L23_1
L23_1 = "额，这个嘛.....我们也不知道原因。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Hm, ich bin mir nicht sicher. Wir wissen auch nicht genau, warum."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Hum... J'en suis pas sûr. À vrai dire, on nous a jamais donné la raison exacte."
L22_1.m_Talk_FRA = L23_1
