L24_1 = "MEMBER2_NPC_MILITIA_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "R"
L24_1 = "난 그 때 지하철 수색하러 온 짭새들 때문이라고 생각한다."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "俺はあの時地下鉄の捜索をしに来たマッポのせいだと思う。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "I bet it's because of those cops who was snooping around the subway."
L23_1.m_Talk_ENG = L24_1
L24_1 = "我認為是因為那時來地鐵搜查的條子！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "แต่ผมมั่นใจว่าเพราะพวกตำรวจที่ตามส่องอยู่แถวรถไฟใต้ดินนะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Tôi cá rằng đó là vì những cảnh sát đã rình mò trên tàu điện ngầm."
L23_1.m_Talk_VTN = L24_1
L24_1 = "我认为可能是因为来地铁搜查的条子们。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Ich wette, das liegt an diesen Bullen, die in der U-Bahn rumgeschnüffelt haben."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Je suis persuadé que ces à cause de ces flics qui fouinaient dans le métro."
L23_1.m_Talk_FRA = L24_1
