L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "R"
L24_1.m_Crash = 20
L25_1 = "그 생글생글 웃고 다니던 여자 경찰! 사실은 무서운 악연으로 묶여 있는 거야!"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "あのニヤニヤと笑っていた女警察！　実は恐ろしい悪縁で結ばれていたとかな！"
L24_1.m_Talk_JPN = L25_1
L25_1 = "You know, that officer lady with the creepy smile! There must be some kind of bad blood between them!"
L24_1.m_Talk_ENG = L25_1
L25_1 = "那個笑咪咪的女警官！雖然第一次見面的場合不太好！"
L24_1.m_Talk_TWN = L25_1
L25_1 = "เจ้าหน้าที่หญิงที่ยิ้มน่าขนลุกคนนั้นน่ะ! ท่าทางคงเกลียดกันแน่ๆ!"
L24_1.m_Talk_THA = L25_1
L25_1 = "Cô biết không, nữ sĩ quan với nụ cười đáng sợ đó! Giữa họ hẳn phải có thù hằn ghê gớm lắm!"
L24_1.m_Talk_VTN = L25_1
L25_1 = "那个一直笑嘻嘻的女警察！应该与他有纠缠不清的旧怨！"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Diese Polizistin mit dem permanenten Lächeln! Sie sind bestimmt verfeindet!"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Tu sais, cette femme officier avec son sourire flippant ! Je suis sûr qu'il devait y avoir un truc pas net entre eux."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
