L29_1 = "UNIT_SERIOUS"
L28_1.m_Face = L29_1
L28_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L28_1.m_Pos = "C"
L29_1 = "그런데 민우 아저씨가 없으면 어떡해? 오빠들만으로는 어림도 없잖아?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "でもマツダおじさんなしでこれからどうするの？　お兄ちゃんたちだけじゃ色々無理じゃない？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "But what are you going to do now that Mr. Minwoo's gone? There's no way you guys can handle this on your own, is there?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "不過民宇叔叔不在的話，怎麼辦？畢竟你們也沒什麼用。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "แต่พอคุณมิวูไม่อยู่แล้วพวกคุณจะทำยังไงกันคะ? พวกคุณไม่มีทางจัดการกันเองได้หรอก ใช่มั้ยนะ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Nhưng các anh định làm gì bây giờ khi anh Minwoo đã đi mất? Các anh không thể nào tự mình giải quyết việc này, phải không?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "但是民宇大叔不在的话该怎么办？靠各位哥哥行得通吗？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Aber wie kommt ihr ohne Minwoo klar? Allein seid ihr doch unterbesetzt."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Mais qu'est-ce que vous allez faire maintenant que M'sieur Minwoo est parti ? Vous n'y arriverai jamais tout seuls !"
L28_1.m_Talk_FRA = L29_1
