L34_1 = "리 오빠?! 니나 언니도 왔네?!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "リー兄ちゃん？！　ニーナ姉ちゃんも来たの！？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Lee?! Nina too?! You're back?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "李哥哥？！妮娜姊姊也來啦？！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ลีเหรอ?! นีน่าก็ด้วย?! กลับมากันแล้วเหรอ?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Lee?! Cả Nina nữa?! Mọi người đã quay lại?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "李·德佛哥哥？！妮娜姐姐也来了？！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Lee?! Und Nina?! Ihr seid zurück?!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Lee ?! Et Nina ?! Vous êtes de retour ?!"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "HORIZON_ACT6_EPILOGUE2@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3500611
L34_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_LAUGH"
L34_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L34_1.m_Pos = "C"
L35_1 = "출세한 사람들이 웬일이래? 그라운드 원에서 태스크포스 일 하는 거 아니었어?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "出世した人たちがこんなところでどうしたの？　グラウンド・ワンでタスクフォースカンパニーの仕事をしていたんじゃなかったの？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "What are you big shots doing back here? Didn't you get into a TASKFORCE in Ground One?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "什麼風把兩位大紅人吹來啦？你們不是在G1辦特遣勢力的事嗎？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "คนสำคัญอย่างพวกเธอกลับมาทำอะไรที่นี่เนี่ย? ไม่ได้เข้าทาสก์ฟอร์สในกราวด์วันกันไปแล้วเหรอ?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Mọi người đang làm gì ở đây? Chẳng phải mấy người đã tham gia TASKFORCE ở Ground One sao?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "已经出人头地了，为什么还要回来？不是在G1给特遣势力效力吗？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Ihr macht doch jetzt Karriere. Was macht ihr hier? Seid ihr nicht in einer TASKFORCE in Ground One?"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Que nous vaut cet honneur ? Je croyais que vous aviez rejoint une TASKFORCE du Site n°1 ?"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
