L38_1 = "HORIZON_ACT6_EPILOGUE2@87#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3500611
L37_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_LAUGH"
L38_1 = "LEE_FRONTIER_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "R"
L38_1 = "우리 대장님 때문에. 고향에 심상치 않은 일이 터졌다고 해서 걱정이 많더라고."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "うちの隊長様のせいでな。故郷に物騒な事件が起きたと聞いて心配になって来たんだ。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "It's all because of our captain here. She was worried sick about what's been going on back in our hometown."
L37_1.m_Talk_ENG = L38_1
L38_1 = "還不都是我們隊長，說故鄉發生不尋常的事，害我很擔心。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ก็เพราะหัวหน้าเราที่นี่แหละ เธอกังวลจัดว่าเกิดอะไรขึ้นที่บ้านเกิด"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tất cả là do đội trưởng của chúng tôi ở đây. Cô ấy lo lắng phát ốm về những gì đang xảy ra ở quê hương của chúng ta."
L37_1.m_Talk_VTN = L38_1
L38_1 = "是因为队长。听说故乡发生了不寻常的事件后，非常担心。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Das liegt alles an unserem Captain hier. Sie war krank vor Sorge darüber, was in unserer Heimatstadt vor sich geht."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Tout ça c'est grâce à notre capitaine ici présente. Elle était morte d'inquiétude à cause de tout ce qui se passe dans notre petit quartier natal."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "HORIZON_ACT6_EPILOGUE2@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3500611
L38_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "NINA_FRONTIER_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "L"
L39_1 = "뉴스 보자마자 먹던 라면 뿜고 뛰쳐 나가던 건 너야."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ニュースを見るやいなや、食べていたカップ麵を噴き出して飛び出てきたのは君だろう。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "You're the one who darted out the moment you saw the news."
L38_1.m_Talk_ENG = L39_1
L39_1 = "是誰一看到新聞，就吐掉嘴裡的泡麵衝出去的？是你好嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "คนที่ได้ยินข่าวแล้วก็พุ่งปรู๊ดออกไปเลยน่ะมันเธอนะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Cô là người đã bỏ đi ngay khi nhìn thấy tin tức."
L38_1.m_Talk_VTN = L39_1
L39_1 = "看到新闻后，放下吃了一半的泡面跑出去的可是你。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Du bist doch selbst mitten beim Nudeln essen rausgerannt, als du die Nachrichten gesehen hast."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Je te rappelle que c'est toi qui t'es dépêché de sortir lorsque tu as entendu les informations à la télé."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "HORIZON_ACT6_EPILOGUE2@89#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 89
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3500611
L39_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "NINA_FRONTIER_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "L"
L40_1 = "그 사이에 키가 많이 컸네, 레이첼? 요즘 그래피티는 어때?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "見ない間に背が伸びたな、レイチェル。最近もグラフィティをやってるのか？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "You've grown taller than the last time we saw you, Rachel. How's the graffiti coming along these days?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "瑞秋，你這段時間長高不少喔！最近塗鴉如何？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เธอสูงกว่าที่เจอกันคราวก่อนนะเนี่ยเรเชล เดี๋ยวนี้กราฟิติเป็นไงบ้างแล้วล่ะ?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Em đã cao hơn lần cuối lúc bọn chị nhìn thấy em đấy, Rachel. Graffiti ra sao rồi?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "这段时间你好像长高了不少吧，雷切尔？最近还在玩涂鸦吗？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Du bist ganz schön groß geworden, Rachel. Wie läuft deine Graffitikunst heutzutage?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "On dirait que tu as bien grandi depuis la dernière fois, Rachel. Tu fais toujours des graffitis ?"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
