L42_1 = "UNIT_PRIDE"
L41_1.m_Face = L42_1
L41_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L41_1.m_Pos = "C"
L41_1.m_Crash = 10
L42_1 = "전보다 더 끝내주지! 언니가 필요하다면 멋진 걸로 즉석에서 하나 해 줄 수도 있는데?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "もちろん、前より上達したよ！　姉ちゃんが欲しいなら、ちょーイケてるやつを今すぐ描いてあげようか？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Oh, I got even better than before! I could make an awesome one right here if you'd like to see!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "當然是比之前更厲害囉！姊姊想要嗎？我可以立刻畫一幅厲害的給你！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "อ๋อ ฉันเก่งกว่าเมื่อก่อนแล้วนะ! ถ้าอยากเห็นเดี๋ยวจัดเด็ดๆ ให้ตรงนี้เลย!"
L41_1.m_Talk_THA = L42_1
L42_1 = "Oh,thậm chí còn tốt hơn trước đây! Em có thể tạo ra một bức tranh tuyệt vời ngay tại đây nếu mọi người muốn xem!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "比之前更棒了！如果姐姐你需要，我可以现场给你画一个漂亮的哦？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Oh, ich bin noch viel besser geworden! Ich könnte hier eines herzaubern, wenn ihr es sehen möchtet!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Oh, je suis encore plus douée qu'avant ! Je pourrais vous en faire un super cool maintenant, si vous le voulez !"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
