L48_1 = "HORIZON_ACT6_EPILOGUE2@97#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 97
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3500611
L47_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "LEE_FRONTIER_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "R"
L47_1.m_Crash = 10
L48_1 = "아, 그러고 보니 마야한테 하트베리 방송 보여 주려고 트렁크에서 태블릿 꺼냈는데……."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "あ、そういえばマヤにハートベリーの配信を見せようとトランクからタブレットを出しておいたが……"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Come to think of it, I took out the tablet from the trunk so Maya could watch the HRT Berry show…"
L47_1.m_Talk_ENG = L48_1
L48_1 = "突然想到，我要給瑪雅看愛心莓果的直播，就從箱子裡拿出平板……"
L47_1.m_Talk_TWN = L48_1
L48_1 = "มานึกดูแล้วนี่ ฉันเอาแท็บเล็ตออกมาจากหลังรถเพราะมายาจะได้ดูรายการของ HRT เบอร์รี่นี่..."
L47_1.m_Talk_THA = L48_1
L48_1 = "Nghĩ lại, tôi đã lấy máy tính bảng ra khỏi cốp xe để Maya có thể xem chương trình HRT Berry…"
L47_1.m_Talk_VTN = L48_1
L48_1 = "啊，刚才想给玛雅看爱心莓果的视频，在后备箱拿过平板电脑……"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Ach ja, ich habe das Tablet aus dem Kofferraum geholt, damit Maya die HRT Berry-Show sehen kann ..."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Maintenant que j'y pense, j'ai sorti la tablette du coffre pour que Maya puisse regarder l'émission d'HRT Berry..."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "HORIZON_ACT6_EPILOGUE2@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3500611
L48_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "UNIT_SERIOUS"
L48_1.m_Face = L49_1
L49_1 = "NINA_FRONTIER_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "L"
L48_1.m_Crash = 20
L49_1 = "너 설마 그러고 안 잠궜어?! 그 안에 로켓포 들어 있잖아!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "もしかして、鍵をかけなかったのか？　トランクの中にはロケット砲が入っているだろ！？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Did you forget to lock the trunk?! The RPG's in there!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "你沒把它關好嗎？！裡面裝的是炸藥欸！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ลืมล็อกกระโปรงหลังปะเนี่ย?! ในนั้นมี RPG นะ!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Cô đã quên khóa cốp xe rồi?! RPG đang ở trong đó!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "你不会忘了锁吧？那里边放着火箭炮！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Hast du etwa vergessen, den Kofferraum abzuschließen?! Der Raketenwerfer ist da drin!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Ne me dis pas que tu as oublié de fermer le coffre à clé ?! Le lance-roquettes est à l'intérieur !"
L48_1.m_Talk_FRA = L49_1
