L51_1 = "좀 있다 다시 얘기하자, 레이첼! 험비 피자가게에서 피자 한 판 먹으면서!"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "後でまた話そう、レイチェル！　ハンヴィのピザ屋さんでな！"
L50_1.m_Talk_JPN = L51_1
L51_1 = "We'll have to catch up later, Rachel! Let's grab a pie at the Humvee Pizzeria!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "瑞秋，我們晚點再聊！一邊吃披薩一邊聊！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ค่อยถามสารทุกข์สุกดิบกันทีหลังนะเรเชล! ไว้ไปกินพายที่ฮัมวีพิซเซอเรียกัน!"
L50_1.m_Talk_THA = L51_1
L51_1 = "Chúng ta sẽ gặp nhau sau, Rachel! Hãy lấy một chiếc bánh tại Humvee Pizzeria đi!"
L50_1.m_Talk_VTN = L51_1
L51_1 = "一会再聊，雷切尔！我请你去突击车披萨店吃披萨！"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Reden wir später weiter, Rachel! Über eine Pizza in der Pizzeria Humvee!"
L50_1.m_Talk_DEU = L51_1
L51_1 = "On rattrapera le temps perdu un peu plus tard, Rachel ! On mangera un bout à la pizzeria Humvee !"
L50_1.m_Talk_FRA = L51_1
