L3_1.m_Face = "UNIT_IDLE"
L3_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L3_1.m_Pos = "C"
L4_1 = "그래서 두 사람, 호라이즌 소식은 뭐 들은 거 없어?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "それで二人は、ホライズンについて何か知らないの？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "So… Have you two heard anything about Horizon?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "喂，你們兩個，有聽說什麼地平線的消息嗎？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แล้ว... คุณสองคนได้ยินเรื่องฮอไรซันบ้างมั้ยคะ?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Vậy… Hai anh đã nghe nói gì về Horizon chưa?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "所以你们两个，有听说过地平线的消息吗？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Also ... habt ihr beide etwas über Horizon gehört?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Bon et du coup... Vous avez entendu quelque chose à propos d'Horizon ?"
L3_1.m_Talk_FRA = L4_1
