L7_1 = "MEMBER_NPC_MILITIA_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "L"
L7_1 = "아, 그 애 말이지. 별다른 소식은 안 들렸는데……."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "ああ、あの子か。特に噂とかはなかったが……"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Oh, that kid? Nothing special, really…"
L6_1.m_Talk_ENG = L7_1
L7_1 = "喔～你說那個孩子喔，是沒聽到什麼消息……"
L6_1.m_Talk_TWN = L7_1
L7_1 = "อ๋อ เด็กคนนั้นนะเหรอ? จริงๆ ก็ไม่มีอะไรเป็นพิเศษนะ..."
L6_1.m_Talk_THA = L7_1
L7_1 = "Ồ, đứa trẻ đó? Không có gì đặc biệt, thực sự…"
L6_1.m_Talk_VTN = L7_1
L7_1 = "啊，你是说那个女孩。没听到别的消息……"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Ach, sie? Nein, nichts Besonderes, aber ..."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Oh, elle ? Non pas vraiment..."
L6_1.m_Talk_FRA = L7_1
