L8_1 = "HORIZON_ACT6_EPILOGUE2@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3500611
L7_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "MEMBER2_NPC_MILITIA_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "R"
L8_1 = "4번가에 그 사무실 있잖아. 며칠 전에 갑자기 공사를 하더라고. 누가 사들였나 봐."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "4番街の事務所があるだろ。数日前から急に工事が始まったんだ。誰かが買い付けたみたいでな。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "You know that office on 4th Avenue? They started construction there out of the blue a few days ago. Someone must have bought the property."
L7_1.m_Talk_ENG = L8_1
L8_1 = "不是在第四大道的辦公室嗎？幾天突然在施工，可能有人買下它吧？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "รู้จักสำนักงานที่โฟร์ทอะเวนิวใช่มะ? อยู่ๆ สองสามวันก่อนก็เริ่มมีการก่อสร้างที่นั่น คงมีใครซื้อไปแล้วน่ะ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Cô biết văn phòng đó trên đại lộ số 4 chứ? Họ đã bắt đầu xây dựng ở đó cách đây vài ngày. Ai đó chắc chắn đã mua lại bất động sản."
L7_1.m_Talk_VTN = L8_1
L8_1 = "4号街区那个办公室。几天前突然开始装修了，可能是被人买了吧。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Kennst du das Büro in der 4. Straße? Sie haben dort vor wenigen Tagen aus heiterem Himmel mit dem Bau begonnen. Jemand muss die Immobilie gekauft haben."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Tu sais, ce bureau sur la 4ème Avenue. Ils se sont mis à faire des travaux de construction tout à coup. On dirait que quelqu'un a racheté la propriété."
L7_1.m_Talk_FRA = L8_1
