L13_1 = "으음. 간판까지 번듯하게 걸렸던데."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "そう。看板までちゃんとかかっていたよ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Mmhmm. It even had a new sign and all."
L12_1.m_Talk_ENG = L13_1
L13_1 = "嗯嗯，還有掛上漂亮的招牌呢～"
L12_1.m_Talk_TWN = L13_1
L13_1 = "อืมมมม มีป้ายใหม่อะไรใหม่หมดเลยนะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Mmhmm. Nó thậm chí còn có một dấu hiệu mới và tất cả."
L12_1.m_Talk_VTN = L13_1
L13_1 = "嗯嗯。还挂上了招牌。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Genau. Es hatte sogar ein neues Schild und so."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Hum... Ils ont même mis un nouveau panneau, et tout."
L12_1.m_Talk_FRA = L13_1
