L13_1.m_fTalkTime = 0.03
L14_1 = "ええと、確か名前は……"
L13_1.m_Talk_JPN = L14_1
L14_1 = "That's right. But I think the name was…"
L13_1.m_Talk_ENG = L14_1
L14_1 = "對啊，只是名字……"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ใช่ แต่ฉันว่าชื่อนี่..."
L13_1.m_Talk_THA = L14_1
L14_1 = "Đúng rồi. Nhưng tôi nghĩ cái tên đó là…"
L13_1.m_Talk_VTN = L14_1
L14_1 = "是啊。名字好像是叫……"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Stimmt. Aber darauf stand ..."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Oui, mais je crois que le nom c'était..."
