L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "誠実に、親切に、真心を込めておもてなしするホライズン・ファンドです。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "At Horizon Finance, the customer comes first."
L16_1.m_Talk_ENG = L17_1
L17_1 = "竭誠為您服務的地平線金融。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ที่ฮอไรซันไฟแนนซ์ ลูกค้าต้องมาก่อนค่ะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tại Horizon Finance, khách hàng là trên hết."
L16_1.m_Talk_VTN = L17_1
L17_1 = "地平线投资基金将会以亲切和热情提供服务。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Hier ist Horizon Finance. Der Kunde steht bei uns an erster Stelle."
L16_1.m_Talk_DEU = L17_1
L17_1 = "À Horizon Finance, la satisfaction de nos clients est notre priorité."
L16_1.m_Talk_FRA = L17_1
