L18_1 = "대출 상담을 하러 오셨습니까, 레이첼."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "ローンの相談でいらっしゃったのですか、レイチェル。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Have you come to apply for a loan, Rachel?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "瑞秋，你有資金需求嗎？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "มาสมัครกู้เงินรึเปล่าคะเรเชล?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Cô đã đến để đăng ký một khoản vay sao, Rachel?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "你是来做贷款商谈的吗，雷切尔。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Bist du hier, um dich für ein Darlehen zu bewerben, Rachel?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Êtes-vous venue faire une demande de prêt, Rachel ?"
