L22_1 = "HORIZON_ACT6_EPILOGUE2@121#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 121
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 3500611
L21_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "HORIZON_HORIZON_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "L"
L21_1.m_Crash = 10
L22_1 = "숨은 안 막히지만 제 프레임을 팔로 조이는 이유에 대해 설명해 주십시오. 레이첼."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "息は苦しくありませんが、私のフレームを腕で締める理由について説明してください、レイチェル。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "While it is impossible to suffocate me, I would like to know why you are applying pressure on my frame with your arms, Rachel."
L21_1.m_Talk_ENG = L22_1
L22_1 = "瑞秋，雖然我還能呼吸，但可以請你解釋一下，為什麼要勒緊我的軀殼嗎？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ถึงจะทำให้ฉันขาดอากาศตายไม่ได้ แต่ฉันก็อยากรู้นะคะเรเชล ว่าทำไมถึงใช้แขนเพิ่มแรงกดดันใส่เฟรมของฉันคะ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Mặc dù không thể làm tôi ngạt thở, nhưng tôi muốn biết tại sao cô lại dùng cánh tay của mình để tạo áp lực lên bộ khung của tôi, Rachel."
L21_1.m_Talk_VTN = L22_1
L22_1 = "虽然不会导致呼吸不畅，但你需要说明为什么要用胳膊锁住我的躯体。雷切尔。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Es ist zwar unmöglich, mich zu ersticken, aber ich würde gerne wissen, warum du mit deinen Armen Druck auf meinen Rahmen ausübst, Rachel."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Bien qu'il soit impossible d'obstruer mon système respiratoire, j'aimerais savoir pourquoi vous exercez une telle force sur mon armature avec vos bras, Rachel."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "HORIZON_ACT6_EPILOGUE2@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3500611
L22_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L22_1.m_bWaitClick = true
