L23_1 = "UNIT_SERIOUS"
L22_1.m_Face = L23_1
L22_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L22_1.m_Pos = "R"
L22_1.m_Crash = 20
L23_1 = "너 재판 받았다며! 얘기 다 들었어! 게다가……!"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "アンタの裁判の話は聞いたよ！　それに……！"
L22_1.m_Talk_JPN = L23_1
L23_1 = "I heard you were on trial! I heard about it all! And…"
L22_1.m_Talk_ENG = L23_1
L23_1 = "我聽說你受審！我都聽說了！而且……！"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ได้ยินว่าเธอต้องขึ้นศาลนี่น่า! ฉันรู้เรื่องหมดแล้ว! แล้ว..."
L22_1.m_Talk_THA = L23_1
L23_1 = "Chị nghe nói em đã ra tòa! Chị đã nghe nói về tất cả! Và…"
L22_1.m_Talk_VTN = L23_1
L23_1 = "不是说你被判刑了吗！我都听说了！还有……！"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ich habe gehört, dass du vor Gericht gestanden hast! Ich habe alles gehört! Und ..."
L22_1.m_Talk_DEU = L23_1
L23_1 = "J'ai entendu dire que tu avais été jugée ! On m'a tout raconté ! Et puis...!"
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "HORIZON_ACT6_EPILOGUE2@123#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3500611
L23_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L23_1.m_bWaitClick = true
