L23_1.m_Face = "UNIT_DESPAIR"
L23_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L23_1.m_Pos = "R"
L23_1.m_Crash = 10
L24_1 = "게다가……. 그 무서운 아저씨들이랑 싸우기도 하고……."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "それに……あの怖いおじさんたちと戦って……"
L23_1.m_Talk_JPN = L24_1
L24_1 = "And... You even fought those scary men…"
L23_1.m_Talk_ENG = L24_1
L24_1 = "而且……你還有和那個可怕的叔叔吵架……"
L23_1.m_Talk_TWN = L24_1
L24_1 = "แล้ว... เธอก็สู้กับพวกคนน่ากลัวๆ นั่นด้วย"
L23_1.m_Talk_THA = L24_1
L24_1 = "Và... Em thậm chí đã chiến đấu với những người đáng sợ đó..."
L23_1.m_Talk_VTN = L24_1
L24_1 = "还有……你和那些吓人的大叔们战斗……"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Und dass du sogar gegen diese furchteinflößenden Männer gekämpft hast ..."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Et puis... Tu t'es battue contre ces types affreux..."
L23_1.m_Talk_FRA = L24_1
