L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "L"
L25_1 = "재판 결과, 보시는 대로 되었습니다."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "裁判の結果、ご覧のとおり平気です。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "The trial concluded in my liberation, as you can see."
L24_1.m_Talk_ENG = L25_1
L25_1 = "審判結果，就如你現在所看到的。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "การพิจารณาคดีจบลงด้วยการที่ฉันเป็นอิสระอย่างที่คุณเห็นค่ะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Phiên tòa kết thúc với tự do của tôi, như cô thấy đấy."
L24_1.m_Talk_VTN = L25_1
L25_1 = "审判结果，就像你看到的这样。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Der Prozess endete mit meiner Befreiung, wie du sehen kannst."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Le procès a conclu sur ma libération, comme vous pouvez le voir."
L24_1.m_Talk_FRA = L25_1
