L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "HORIZON_HORIZON_NULL_NULL"
L28_1.m_CharStrID = L29_1
L29_1 = "코핀 컴퍼니의 주선으로 증언들이 들어온 덕분에 누명은 피할 수 있었습니다."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "コフィンカンパニー主導のもとで証言があったおかげで、濡れ衣は晴らされました。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Thanks to the Coffin Company's mediation, testimony was secured to dispel the false charges against me."
L28_1.m_Talk_ENG = L29_1
L29_1 = "都是因為有科芬公司替我找到證據，我才能洗刷污名。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ต้องขอบคุณการไกล่เกลี่ยของบริษัทคอฟฟินนะคะ การรวบรวมพยานหลักฐานทำให้ข้อกล่าวหาที่ฉันได้รับเป็นเท็จค่ะ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Nhờ sự hòa giải của Công Ty Coffin, lời khai đã được bảo đảm để xóa bỏ những cáo buộc sai trái đối với tôi."
L28_1.m_Talk_VTN = L29_1
L29_1 = "在科芬公司的帮助下，有很多证词能证明我无罪。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Dank der Vermittlung der Coffin Company wurde eine Zeugenaussage sichergestellt, mit dem die falschen Anschuldigungen aufgeräumt werden konnten."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Grâce à la médiation de la Compagnie Coffin, les fausses accusations à mon égard ont pu être dissipées."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
