L31_1 = "HORIZON_ACT6_EPILOGUE2@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3500611
L30_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "HORIZON_HORIZON_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "그리고 제프티 바이오테크의 실상이 알려져서 무력 사용의 필요성을 인정 받아……"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "そしてジェフティ・バイオテックの真相が明かされ、武力行使の必要性が認められ……"
L30_1.m_Talk_JPN = L31_1
L31_1 = "And when Jehuty Biotech's true exploits were unveiled, the court ruled in favor of my need to employ kinetic measures…"
L30_1.m_Talk_ENG = L31_1
L31_1 = "再加上傑夫堤生物科技的真面目曝光後，我使用武力的必要性也獲得認可……"
L30_1.m_Talk_TWN = L31_1
L31_1 = "และเมื่อการขูดรีดที่แท้จริงของเจฮูตีไบโอเทคถูกเปิดเผยออกมา ศาลก็มีคำสั่งเห็นพ้องกับฉันว่าต้องใช้มาตรการที่มีการเคลื่อนไหว..."
L30_1.m_Talk_THA = L31_1
L31_1 = "Và khi những hành vi bóc lột thực sự của Jehuty Biotech được tiết lộ, tòa án đã ra phán quyết ủng hộ việc tôi cần phải sử dụng các biện pháp động học…"
L30_1.m_Talk_VTN = L31_1
L31_1 = "还有杰普提生物科技的真面目也被公诸于世，我使用武力也获得了谅解……"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Und als die wahren Machenschaften von Jehuty Biotech enthüllt wurden, entschied das Gericht zugunsten meiner Notwendigkeit, kinetische Maßnahmen anzuwenden ..."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Et lorsque les manigances de Jehuty Biotech ont été dévoilées au grand jour, la Cour a jugé en faveur de l'usage de la force dont j'ai fait preuve..."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
