L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "HORIZON_HORIZON_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "몇 가지 제약 외에는 자유로워졌습니다."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "いくつかの制約はありますが、自由の身になりました。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Save for a few constraints, I am free as a lark, as you humans say."
L32_1.m_Talk_ENG = L33_1
L33_1 = "排除一些限制外，其他都是自由的。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "นอกจากการจำกัดอิสรภาพบางประการแล้ว ฉันก็อิสระเหมือนนกน้อยที่โบยบิน อย่างที่มนุษย์แบบพวกคุณพูดกันน่ะค่ะ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Gỡ bỏ một số ràng buộc, tôi tự do như một con chim sơn ca, như con người các cô hay nói ấy."
L32_1.m_Talk_VTN = L33_1
L33_1 = "除了有几项制约以外，我现在很自由。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Abgesehen von ein paar Einschränkungen bin ich nun frei wie ein Vogel, wie ihr Menschen sagt."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Je suis donc libre comme le vent, comme vous dites. Hormis quelques contraintes."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
