L35_1 = "HORIZON_ACT6_EPILOGUE2@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3500611
L34_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "HORIZON_HORIZON_NULL_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "샤레이드의 전폭적인 지원을 받고 있었기 때문에, 수사 결과는 대외적으로 공표할 수는 없다더군요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "例の会社がシャレードから全面的な支援を受けていたので、捜査結果は対外的に公表できないと言われましたが。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "They could not, however, publicly release the findings of the investigation given the immense support Jehuty Biotech had from Charade."
L34_1.m_Talk_ENG = L35_1
L35_1 = "由於受到查雷德全力的支持，搜查結果無法對外公開。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "แต่ถึงยังไง ความที่เจฮูตีไบโอเทคได้รับการสนับสนุนจากชาเรดอย่างมหาศาล ก็ทำให้พวกเขาเปิดเผยสิ่งที่พบจากการสืบสวนให้สาธารณะรับรู้ไม่ได้ค่ะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Tuy nhiên, họ không thể công bố công khai các phát hiện của cuộc điều tra do sự hẫu thuẫn to lớn mà Jehuty Biotech nhận được từ Charade."
L34_1.m_Talk_VTN = L35_1
L35_1 = "因为杰普提之前获得过查雷德的全力支持，所以调查结果不能对外公开。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Sie konnten die Ergebnisse der Untersuchung jedoch angesichts der immensen Unterstützung, die Jehuty Biotech von Charade erhält, nicht öffentlich machen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Cependant, ils n'étaient pas en mesure de rendre officiels les résultats de l'enquête, à cause de l'énorme soutien que Jehuty Biotech recevait de Charade."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
