L38_1 = "HORIZON_ACT6_EPILOGUE2@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3500611
L37_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L37_1.m_Pos = "C"
L37_1.m_Crash = 15
L38_1 = "다행이다……. 평생 감옥에 있을 줄 알았잖아……."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "よかった……一生刑務所暮らしになると思っていたの……"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Thank goodness… I was afraid you'd end up in jail for life…"
L37_1.m_Talk_ENG = L38_1
L38_1 = "太好了……我還以為你這輩子都要吃牢飯了……"
L37_1.m_Talk_TWN = L38_1
L38_1 = "โล่งอกไปที... ฉันละกลัวว่าเธอจะต้องติดคุกไปตลอดชีวิตแล้ว..."
L37_1.m_Talk_THA = L38_1
L38_1 = "Cảm ơn trời đất… chị sợ rằng em sẽ phải ngồi tù cả đời…"
L37_1.m_Talk_VTN = L38_1
L38_1 = "真是万幸……我还以为你会一辈子关在监狱里……"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Gott sei Dank ... Ich hatte Angst, dass du lebenslang hinter Gittern landen würdest ..."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Dieu merci... J'ai bien cru que tu allais finir en prison pour le reste de ta vie..."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "HORIZON_ACT6_EPILOGUE2@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3500611
L38_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_SURPRISE"
L38_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "그런데 제약이라니? 수갑은 안 차고 있는데?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ところで制約って？　手錠は見当たらないけど？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "But what's this about constraints? I don't see you wearing any cuffs."
L38_1.m_Talk_ENG = L39_1
L39_1 = "不過限制是什麼？你沒帶手銬啊？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แล้วที่ว่าจำกัดอิสรภาพนี่อะไรล่ะ? ไม่เห็นเธอต้องสวมกุญแจมือเลย"
L38_1.m_Talk_THA = L39_1
L39_1 = "Nhưng còn các ràng buộc thì sao? Chị không thấy em phải đeo còng tay gì cả."
L38_1.m_Talk_VTN = L39_1
L39_1 = "但制约是指什么？你没带手铐啊？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Aber welche Einschränkungen meinst du? Du trägst keine Handschellen."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Mais de quelles contraintes tu parles ? Tu ne portes pas de menottes que je sache ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "HORIZON_ACT6_EPILOGUE2@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3500611
L39_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_Face = "UNIT_DESPAIR"
L40_1 = "HORIZON_HORIZON_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "이것저것 많습니다. 가령 관리국의 작전에 협조하라거나 말이죠."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "色々あります。たとえば、管理局の作戦に協力しろとか。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "There's quite a few, actually. For instance, I am to cooperate with the Administration's operations."
L39_1.m_Talk_ENG = L40_1
L40_1 = "很多，像是支援管理局的作戰之類的。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ไม่กี่อย่างจริงๆ ค่ะ ตัวอย่างก็เช่น ฉันต้องให้ความร่วมมือในปฏิบัติการขององค์การบริหารโลก"
L39_1.m_Talk_THA = L40_1
L40_1 = "Thực ra có vài ràng buộc. Ví dụ, tôi phải hợp tác với các hoạt động của Cục Quản Lý."
L39_1.m_Talk_VTN = L40_1
L40_1 = "有各种各样很多。比如要协助管理局的作战什么的。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Es gibt ziemlich viele. Zum Beispiel soll ich mit den Operationen der Administration kooperieren."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Elles ne sont pas des moindres. Par exemple, je dois coopérer lors des opérations de l'Administration."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "HORIZON_ACT6_EPILOGUE2@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3500611
L40_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "HORIZON_HORIZON_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "담당자 이야기로는 최상부에서 모종의 압력이 들어왔다고도 합니다만."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "担当者の話では、最上部から何らかの圧力がかかってきたそうですが。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "My lawyer suspects that there has been a certain amount of pressure levied by the highest echelons of the Administration's leadership."
L40_1.m_Talk_ENG = L41_1
L41_1 = "據負責人的說法，是有來自最高層的某種壓力。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ทนายความของฉันสงสัยว่าจะมีแรงกดดันมาจาก\nผู้นำในระดับสูงสุดขององค์การบริหารโลกค่ะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Luật sư của tôi nghi ngờ rằng đã có một số áp lực nhất định từ các cấp cao nhất của ban lãnh đạo Cục Quản Lý."
L40_1.m_Talk_VTN = L41_1
L41_1 = "根据负责人所说，是最高层向他们施压了。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Mein Anwalt vermutet, dass die höchsten Führungsebenen einen gewissen Druck ausgeübt haben."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Mon avocat soupçonne qu'il y a eu une certaine pression exercée par les hauts gradés."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "HORIZON_ACT6_EPILOGUE2@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3500611
L41_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_Face = "UNIT_IDLE"
L42_1 = "HORIZON_HORIZON_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "C"
L42_1 = "궁상맞은 이야기는 이쯤 하고, 입원 생활로 고생했을 레이첼에게 마실 것이라도 드리겠습니다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "つまらない話はこの辺にして、入院生活で苦労したレイチェルに飲み物でも出します。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Enough of this boring legal talk. Perhaps I can offer you a beverage to celebrate your release from the hospital."
L41_1.m_Talk_ENG = L42_1
L42_1 = "我的事就說到這裡，給住院的瑞秋來點喝的吧。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เรื่องกฎหมายน่าเบื่อพอแค่นี้เถอะนะคะ บางทีฉันน่าจะหาอะไรให้คุณดื่มฉลองที่ถูกปล่อยตัวจากโรงพยาบาลซะหน่อย"
L41_1.m_Talk_THA = L42_1
L42_1 = "Cuộc nói chuyện pháp lý nhàm chán này đủ rồi. Có lẽ tôi có thể mời cô một ly nước giải khát để kỷ niệm ngày cô xuất viện."
L41_1.m_Talk_VTN = L42_1
L42_1 = "无聊的故事就到此为止。现在请让我为在医院生活中受苦的雷切尔准备一杯饮料吧。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Genug von diesem langweiligen Rechtsgerede. Kann ich dir ein Getränk anbieten, um deine Entlassung aus dem Krankenhaus zu feiern?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Mais assez tergiversé sur ces problèmes légaux. Laissez-moi vous offrir une boisson pour vous féliciter de votre rémission."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
