L45_1 = "HORIZON_ACT6_EPILOGUE2@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3500611
L44_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_Face = "UNIT_LAUGH"
L44_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L44_1.m_Pos = "R"
L44_1.m_Crash = 20
L45_1 = "아, 그럼 난 위스키!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "そうね。それじゃあ、アタシはウイスキー！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Ooh, then I'd like some whiskey, please!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "喔！那我要威士忌！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "โอ้ ถ้างั้นฉันขอวิสกี้นะ!"
L44_1.m_Talk_THA = L45_1
L45_1 = "Ồ, vậy chị muốn một ít rượu whisky, làm ơn đi mà!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "啊，那我要喝威士忌酒！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ooh, dann möchte ich bitte etwas Whiskey!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Oh ! Dans ce cas, je prendrai un whisky !"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "HORIZON_ACT6_EPILOGUE2@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3500611
L45_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "HORIZON_HORIZON_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "L"
L46_1 = "저희 사무실은 미성년자에게 술을 주지 않습니다."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "うちの事務所では未成年者にお酒は提供しません。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "This office strictly complies with the legal drinking age."
L45_1.m_Talk_ENG = L46_1
L46_1 = "我們辦公室不提供未成年酒類。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "สำนักงานนี้เข้มงวดเรื่องอายุผู้ดื่มแอลกอฮอล์ตามกฎหมายนะคะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Văn phòng này tuân thủ nghiêm ngặt quy định về độ tuổi uống rượu hợp pháp."
L45_1.m_Talk_VTN = L46_1
L46_1 = "我们办公室不会给未成年人提供酒精饮料。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Dieses Büro hält sich strikt an das gesetzliche Mindestalter für den Konsum von Alkohol."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Nous ne proposons pas de boissons alcoolisées aux mineurs dans ce bureau."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "HORIZON_ACT6_EPILOGUE2@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3500611
L46_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_DESPAIR"
L46_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L46_1.m_Pos = "R"
L46_1.m_Crash = 10
L47_1 = "아깝다. 원래 퇴원하고 나온 다음에는 맛깔나게 한 잔 캬-! 해 줘야 하는데."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ざんねーん。退院祝いに一杯飲んで、くう～！　酒がうまい！　ってやるのがロマンだったのに。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Aw, shucks. I was looking forward to downing a shot after getting out of the hospital. You know, like they do in movies."
L46_1.m_Talk_ENG = L47_1
L47_1 = "真可惜～本來想說出院後可以痛快乾～一杯的！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "โธ่ ไอ้เราก็อุตส่าห์รอจะยกสักเป๊กหลังออกจากโรงพยาบาล แบบที่ทำกันในหนังอะ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ồ chán thế. Chị đã mong được uống một ly sau khi xuất viện. Em biết đấy, giống như họ làm trong mấy bộ phim."
L46_1.m_Talk_VTN = L47_1
L47_1 = "真可惜。通常出院后就应该来一杯酒庆祝下。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ach, schade. Ich habe mich auf einen starken Tropfen gefreut, nachdem ich aus dem Krankenhaus entlassen wurde. So, wie sie es in Filmen tun."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Dommage. J'espérais faire un cul-sec comme ils font dans les films après être sorti de l'hôpital."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "HORIZON_ACT6_EPILOGUE2@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3500611
L47_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "HORIZON_HORIZON_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "L"
L48_1 = "어디서 보고 들은 건 있어 가지고 주접이시군요."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "入院中にドラマを観すぎたようですね。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "You've been watching too many movies, indeed."
L47_1.m_Talk_ENG = L48_1
L48_1 = "這又是從哪來聽來的？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "คุณดูหนังมากไปแล้วค่ะ จริงๆ นะคะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Quả thực là cô đã xem quá nhiều phim rồi đấy."
L47_1.m_Talk_VTN = L48_1
L48_1 = "也不知道你是从哪里学来的。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Du hast zu viele Filme gesehen."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Vous regardez trop de films, en effet."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
