L51_1 = "HORIZON_HORIZON_NULL_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L51_1 = "그래서 레이첼, 확인차 물어 보겠습니다."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "それでレイチェル、確認のため一つ聞きたいことがあります。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Speaking of legal age, I do something I wish verify with you."
L50_1.m_Talk_ENG = L51_1
L51_1 = "所以，瑞秋，我跟你確認一下。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "พูดถึงเรื่องอายุตามกฎหมายแล้วนี่ ฉันไปทำอะไรที่ต้องยืนยันกับเธอมาล่ะ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Nói về độ tuổi hợp pháp, tôi muốn xác minh với cô."
L50_1.m_Talk_VTN = L51_1
L51_1 = "所以雷切尔，我想问你个问题。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Apropos Volljährigkeit, ich frage dich jetzt etwas, Rachel."
L50_1.m_Talk_DEU = L51_1
L51_1 = "En parlant d'âge légal, il y a quelque chose que je souhaite vous demander."
L50_1.m_Talk_FRA = L51_1
