L2_1 = "HORIZON_ACT6_EPILOGUE2@151#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 151
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 3500611
L1_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "HORIZON_HORIZON_NULL_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "현재 독립을 준비해야 할 상황입니까."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "現在、独立を準備しなければならない状況ですか。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Are you at a juncture where you must now move out and stand on your own?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "你現在是必須預備獨立的時候嗎？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "คุณมาถึงจุดหัวเลี้ยวหัวต่อที่ต้องย้ายออกมายืนด้วยลำแข้งตัวเองแล้วเหรอคะ?"
L1_1.m_Talk_THA = L2_1
L2_1 = "Cô đã đến lúc phải chuyển ra ngoài và tự đứng trên đôi chân của mình chưa?"
L1_1.m_Talk_VTN = L2_1
L2_1 = "现在你是要准备独立生活了吗？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Bist du an einem Punkt im Leben angelangt, an dem du ausziehen und auf eigenen Beinen stehen musst?"
L1_1.m_Talk_DEU = L2_1
L2_1 = "N'êtes-vous pas à cette étape de votre vie où vous devez prendre votre indépendance ?"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "HORIZON_ACT6_EPILOGUE2@152#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 3500611
L2_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_HATE"
L2_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L2_1.m_Pos = "C"
L2_1.m_Crash = 20
L3_1 = "윽. 갑자기 현실적인 이야기로 찌르긴."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "むう、急に現実的な話か。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Ugh. Way to get all serious and realistic all of a sudden."
L2_1.m_Talk_ENG = L3_1
L3_1 = "唔，怎麼突然問我這麼現實的問題？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ง่ะ อยู่ๆ ก็จริงจังอย่างกับม้าขึ้นมาเลยแฮะ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Ugh. Tự nhiên lại nói chuyện nghiêm túc và thực tế vậy à."
L2_1.m_Talk_VTN = L3_1
L3_1 = "呃。怎么突然问这么现实的问题。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Urgh. Wieso wirst du plötzlich so ernst und realistisch?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Huh... C'est quoi cette discussion super sérieuse tout à coup ?"
L2_1.m_Talk_FRA = L3_1
