L6_1 = "HORIZON_ACT6_EPILOGUE2@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3500611
L5_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_DESPAIR"
L5_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L5_1.m_Pos = "R"
L6_1 = "맞아. 다 컸는데 언제까지 보육원에 신세 지고 있을 수는 없으니까."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "そうね。もう少しで成人するから、いつまでも孤児院のお世話になるわけにはいかないね。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "But you're right. I can't mooch off the orphanage all my life. I'm too old for that now."
L5_1.m_Talk_ENG = L6_1
L6_1 = "沒錯，我都長大了，也不好意思一直賴在育幼院。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "แต่ก็ใช่แหละ ฉันจะไปพึ่งเงินจากบ้านเด็กกำพร้าไปทั้งชีวิตไม่ได้ไง ฉันแก่เกินจะทำแบบนั้นแล้ว"
L5_1.m_Talk_THA = L6_1
L6_1 = "Nhưng em nói đúng. Chị không thể ở trại trẻ mồ côi cả đời. Giờ chị quá tuổi rồi."
L5_1.m_Talk_VTN = L6_1
L6_1 = "是的。毕竟已经长这么大了，没办法一直留在孤儿院添麻烦。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Aber du hast recht. Ich kann nicht mein ganzes Leben lang im Waisenhaus bleiben. Dafür bin ich nun zu alt."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Mais tu as raison. Je ne peux pas continuer à dépendre de l'orphelinat toute ma vie. Je suis trop grande pour ça, maintenant."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "HORIZON_ACT6_EPILOGUE2@156#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 156
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3500611
L6_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "HORIZON_HORIZON_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "L"
L7_1 = "그렇다면 제 사무실에서 일하시죠. 월급은 섭섭하지 않게 지급하겠습니다."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "ならば私の事務所で働いてください。給料は人並みに支給します。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Then I extend an invitation to work in my office. I assure you that the paycheck will not be disappointing."
L6_1.m_Talk_ENG = L7_1
L7_1 = "那你來我辦公室工作吧。薪水不會讓你失望的。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ถ้าอย่างนั้นฉันขอเสนอคำเชิญให้มาทำงานที่สำนักงานของฉันค่ะ รับรองเลยนะคะว่าค่าตอบแทนนี่ไม่ผิดหวังแน่นอน"
L6_1.m_Talk_THA = L7_1
L7_1 = "Vậy thì tôi gia hạn lời mời làm việc tại văn phòng của tôi với cô. Tôi đảm bảo với cô rằng tiền lương sẽ không làm cô thất vọng."
L6_1.m_Talk_VTN = L7_1
L7_1 = "那在我的办公室工作怎么样。工资不会让你失望的。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Dann lade ich dich ein, in meinem Büro zu arbeiten. Ich versichere dir, dass der Gehaltsscheck nicht enttäuschend sein wird."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Dans ce cas, permettez-moi de vous faire une proposition d'emploi. Je peux vous assurer que le salaire ne vous décevra pas."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "HORIZON_ACT6_EPILOGUE2@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3500611
