L9_1 = "HORIZON_ACT6_EPILOGUE2@158#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3500611
L8_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "UNIT_PRIDE"
L8_1.m_Face = L9_1
L8_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L8_1.m_Pos = "R"
L9_1 = "헤헤, 스카우트라니 좋지만 어쩐다. 나는 사채업이랑은 관련이 없는 사람인데."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "ヘヘッ、スカウトは嬉しいけどどうしよう。アタシは闇金業界にはまったく知識がないの。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Wow, I'm flattered that you'd make me a job offer… But I'm afraid I know nothing about being a loan shark."
L8_1.m_Talk_ENG = L9_1
L9_1 = "嘿嘿，有人挖角當然好，但我沒當過放高利貸的欸？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "โห ฉันปลื้มนะเนี่ยที่เธอเสนองานให้อะ... แต่ฉันกลัวว่าตัวเองจะไม่รู้อะไรเรื่องเป็นเจ้าหนี้หน้าเลือดเลยนะสิ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Chà, chị rất vui vì em đã cho chị một lời mời làm việc… Nhưng chị sợ chị không biết gì về việc trở thành một kẻ cho vay nặng lãi."
L8_1.m_Talk_VTN = L9_1
L9_1 = "嘿嘿。能收到你的提议我很高兴，但我从来没接触过高利贷行业，怎么办。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Hehe, dieses Jobangebot schmeichelt mir. Aber leider habe ich mit dem Kreditgeschäft nichts am Hut."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Hé hé ! Je suis flattée que tu me proposes un poste dans ton bureau. Mais tu sais, je n'y connais rien du tout au travail d'usurier."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "HORIZON_ACT6_EPILOGUE2@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3500611
L9_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "HORIZON_HORIZON_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "L"
L10_1 = "괜찮습니다. 얼굴이 팔릴 대로 팔려서 사채업만으로 먹고 살기에는 글렀거든요."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "大丈夫です。私の顔は知られすぎて、闇金融だけで食べていくには厳しいです。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Don't worry. You are already too well known among this community to shake down anyone for payment."
L9_1.m_Talk_ENG = L10_1
L10_1 = "沒問題，現在已經不是靠放高利貸就活得下去的時代。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ไม่ต้องห่วงนะคะ คุณเป็นที่รู้จักดียิ่งกว่าดีในชุมชมนี้จนเก็บเงินจากใครก็ได้ทั้งนั้นแหละค่ะ"
L9_1.m_Talk_THA = L10_1
L10_1 = "Đừng lo lắng. Cô đã quá nổi tiếng trong cộng đồng này để chấn chỉnh bất kỳ ai dám trốn nợ rồi mà."
L9_1.m_Talk_VTN = L10_1
L10_1 = "没关系。因为现在大家都认识我的脸，所以要光靠高利贷养家糊口比较难。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Mach dir keine Sorgen. Du bist in dieser Community zu bekannt, um vom Kreditgeschäft leben zu können."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Pas d'inquiétude. Vous êtes bien trop talentueuse pour vous rabaisser à extorquer de l'argent aux débiteurs."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "HORIZON_ACT6_EPILOGUE2@160#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 3500611
L10_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "HORIZON_HORIZON_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "L"
L11_1 = "간판을 보셨겠지만, 저는 앞으로 조금 더 떳떳하고 장기적인 투자도 계획하고 있습니다."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "すでに看板を見ていると思いますが、私はこれからもう少し堂々とした、長期的な投資を計画しています。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "As you may have noted in the new sign, I plan on investing in more… sanitary endeavors in the long term."
L10_1.m_Talk_ENG = L11_1
L11_1 = "你應該也有看到招牌。我現在正在規劃可以長期經營的正當投資。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "และคุณอาจเห็นจากป้ายใหม่แล้ว ฉันมีแผนว่าจะลงทุนให้มากขึ้นในด้าน... ความพยายามด้านสุขอนามัยในระยะยาวค่ะ"
L10_1.m_Talk_THA = L11_1
L11_1 = "Như cô có thể đã lưu ý trong bảng hiệu mới, tôi dự định đầu tư vào các... hoạt động vệ sinh hơn trong dài hạn."
L10_1.m_Talk_VTN = L11_1
L11_1 = "你看到我们的招牌了吧。我计划以后进行更正当和长期的投资。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Wie du vielleicht auf dem neuen Schild bemerkt hast, plane ich, langfristig in ... legitimere Langzeitprojekte zu investieren."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Comme vous avez sûrement pu le voir sur mon nouveau panneau, je prévois d'investir dans un projet disons... plus honorable sur le long-terme."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
