L12_1 = "장기적인 투자? 암호화폐 말이야?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "長期的な投資？　暗号通貨のこと？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "A long term investment? Like cryptocurrency?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "長期投資？你是指加密貨幣嗎？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "การลงทุนระยะยาว? แบบ เงินคริปโตไรงี้เหรอ?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Một khoản đầu tư dài hạn? Kiểu như tiền điện tử á?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "长期投资？是虚拟货币吗？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Langfristige Investitionen? Wie etwa Kryptowährung?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Un investissement sur le long-terme ? Tu parles des cryptomonnaies ?"
