L13_1 = "HORIZON_HORIZON_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "L"
L13_1 = "……싹수가 있는 휴먼의 장래에 투자하는 겁니다."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "……見込みあるヒューマンの将来に投資することです。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "…I mean an investment in promising humans."
L12_1.m_Talk_ENG = L13_1
L13_1 = "……就是投資未來是潛力股的人類。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "...ฉันหมายถึงลงทุนกับมนุษย์ที่มีแววน่ะค่ะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "… Ý tôi là một khoản đầu tư vào những con người có triển vọng."
L12_1.m_Talk_VTN = L13_1
L13_1 = "……是给有潜力的人类进行长期投资。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ich meine Investitionen in Menschen mit vielversprechenden Potenzialen."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Je veux dire, investir dans des humains avec un avenir prometteur."
L12_1.m_Talk_FRA = L13_1
