L13_1.m_Face = "UNIT_LAUGH"
L13_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L13_1.m_Pos = "R"
L13_1.m_Crash = 20
L14_1 = "그거 내 얘기야?! 어쩐지 아까부터 빤히 보더라!"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "それは私の話！？　どうりでさっきからじろじろ見ていたのねー！"
L13_1.m_Talk_JPN = L14_1
L14_1 = "You mean me? No wonder you've been staring at me funny!"
L13_1.m_Talk_ENG = L14_1
L14_1 = "就是我喔？！難怪你從剛剛就一直盯著我！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "หมายถึงฉันเหรอ? มิน่ามองฉันแปลกๆ!"
L13_1.m_Talk_THA = L14_1
L14_1 = "Ý chị chứ gì? Không có gì ngạc nhiên khi em đang nhìn chằm chằm vào chị một cách buồn cười như thế!"
L13_1.m_Talk_VTN = L14_1
L14_1 = "那不就是在说我吗？怪不得刚才开始就一直在盯着我看！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Du meinst mich? Kein Wunder, dass du mich komisch angestarrt hast!"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Tu parles de moi, là ?! C'est pour ça que tu me dévorais du regard depuis tout à l'heure !"
L13_1.m_Talk_FRA = L14_1
