L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 3500611
L16_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "HORIZON_HORIZON_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "C"
L17_1 = "휴먼들이 장학재단이라고 부르는 것과 유사하죠. 용병도 대상이니 범주는 더 넓습니다만."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "ヒューマンが奨学財団と呼ぶものと似ています。傭兵も対象なので対象範囲はもっと広いですが。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "This would be akin to what humans call a scholarship foundation. Though the range of eligibility is broader, as it will include mercenaries."
L16_1.m_Talk_ENG = L17_1
L17_1 = "就類似人類說的獎學金制度。對象也包含傭兵，範圍很廣。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "นี่อาจคล้ายกับสิ่งที่มนุษย์เรียกว่ามูลนิธิทุนการศึกษาค่ะ ถึงขอบเขตของผู้มีสิทธิ์จะกว้างกว่าเพราะจะรวมทหารรับจ้างด้วยก็ตาม"
L16_1.m_Talk_THA = L17_1
L17_1 = "Điều này tương tự như cái mà con người gọi là quỹ học bổng. Mặc dù phạm vi đủ điều kiện rộng hơn, vì nó sẽ bao gồm cả lính đánh thuê."
L16_1.m_Talk_VTN = L17_1
L17_1 = "我们的业务和人类称为助学基金的东西类似。当然佣兵也是我们的选择对象，所以范围较广。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Dies wäre vergleichbar mit dem, was die Menschen eine Stipendienstiftung nennen. Das Spektrum der Finanzierung ist jedoch breiter, da es Söldner einschließen wird."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Ce dont je parle est similaire à ce que vous autres, les humains, appelez « bourse scolaire ». Mais les critères d'éligibilité seront bien plus variés et incluront les mercenaires."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "HORIZON_ACT6_EPILOGUE2@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 3500611
L17_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_DESPAIR"
L18_1 = "HORIZON_HORIZON_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = "금전 문제로 교육을 받지 못하는 휴먼이나, 가난한 지역의 의뢰를 염가로 받아 주는 용병 등……."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "金銭問題で教育を受けられないヒューマンや、貧しい地域からの依頼を安価で受注してくれる傭兵など……"
L17_1.m_Talk_JPN = L18_1
L18_1 = "It will aid humans such as those who cannot afford education, or mercenaries that take jobs at minimal rates for impoverished neighborhoods."
L17_1.m_Talk_ENG = L18_1
L18_1 = "因為錢的關係而無法上學的人類，或是在貧窮的地區，只能低價接受委託的傭兵等……"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เรื่องนี้จะช่วยเหลือมนุษย์มีเงินไม่พอจะเข้าสู่ระบบการศึกษา หรือทหารรับจ้างที่ทำแต่งานค่าแรงขั้นต่ำให้ย่านที่อยู่อาศัยที่ยากจนค่ะ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Nó sẽ hỗ trợ con người, chẳng hạn như những người không có khả năng chi trả việc học, hoặc những người lính đánh thuê nhận việc làm với mức lương tối thiểu ở những khu dân cư nghèo khó."
L17_1.m_Talk_VTN = L18_1
L18_1 = "诸如因为金钱问题不能获得教育的人类，或者廉价接受贫困地区委托的佣兵等……"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Es wird Menschen helfen, die sich Bildung nicht leisten können, oder Söldnern, die Jobs für verarmte Viertel zu minimalen Preisen annehmen."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Cela donnera un coup de pouce aux humains qui ne peuvent pas se payer de grandes études, ou aux mercenaires qui sont obligés de faire des tâches sous-rémunérées pour des zones défavorisées."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "HORIZON_ACT6_EPILOGUE2@168#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3500611
L18_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Face = "UNIT_IDLE"
L19_1 = "HORIZON_HORIZON_NULL_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "그런 장래가 기대되는 휴먼들에게 저부담 장기 대출을 지원하겠다는 겁니다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "将来が期待されるヒューマンたちに、低負担で長期貸出を支援するのです。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "The goal is to provide long-term low-interest loans to such humans with promising futures."
L18_1.m_Talk_ENG = L19_1
L19_1 = "針對未來有潛力的人類，提供低利率的長期融資。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "เป้าหมายก็คือการให้เงินกู้ระยะยาวดอกเบี้ยต่ำแก่มนุษย์ที่ท่าทางจะมีอนาคตไกลค่ะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Mục đích là cung cấp các khoản vay dài hạn với lãi suất thấp cho những người có tương lai đầy hứa hẹn như vậy."
L18_1.m_Talk_VTN = L19_1
L19_1 = "我想要给未来可期的人类提供低负担的长期贷款。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Das Ziel ist es, solchen vielversprechenden Menschen langfristige, zinsgünstige Kredite zur Verfügung zu stellen."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Mon but et de proposer des emprunts sur le long-terme avec un faible taux d'intérêt aux humains qui ont un avenir prometteur."
L18_1.m_Talk_FRA = L19_1
