L22_1 = "HORIZON_ACT6_EPILOGUE2@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 3500611
L21_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_SURPRISE"
L21_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L21_1.m_Pos = "R"
L21_1.m_Crash = 20
L22_1 = "오오……. 꿈이 참 크시군요, 호라이즌 선생."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "おお……とても大きい夢ですね、ホライズン先生。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Ooh… How ambitious of you, Dr. Horizon."
L21_1.m_Talk_ENG = L22_1
L22_1 = "哇喔……你的野心很大喔，地平線老師。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "โห... ทะเยอทะยานอะไรขนาดนี้คะ ดร.ฮอไรซัน"
L21_1.m_Talk_THA = L22_1
L22_1 = "Ồ… Em thật tham vọng, Tiến sĩ Horizon ạ"
L21_1.m_Talk_VTN = L22_1
L22_1 = "噢噢……你的梦想真伟大。地平线老师。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ooh ... Klingt ehrgeizig von dir, Horizon."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Oh...! C'est un projet ambitieux, madmoiselle Horizon !"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "HORIZON_ACT6_EPILOGUE2@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3500611
L22_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L22_1.m_Pos = "R"
L23_1 = "그런데 갑자기 왜?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "てか急になんで？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "But where did you get this idea all of a sudden?"
L22_1.m_Talk_ENG = L23_1
L23_1 = "但是爲什麼突然？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ว่าแต่อยู่ๆ เธอไปเอาไอเดียแบบนี้มาจากไหนเนี่ย?"
L22_1.m_Talk_THA = L23_1
L23_1 = "Nhưng đột nhiên em có ý tưởng này từ đâu?"
L22_1.m_Talk_VTN = L23_1
L23_1 = "可是为什么要转行呢？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Aber wie kommst du auf einmal auf diese Idee?"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Mais comment t'es venue cette idée tout à coup ?"
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "HORIZON_ACT6_EPILOGUE2@173#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3500611
L23_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "HORIZON_HORIZON_NULL_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "L"
L24_1 = "관리국이 사채업자랑 타협하면 모양새가 나쁘다고 하더군요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "管理局が闇金業者と協力すると面子が立たないと言われました。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "The Administration expressed concerns over the optics of reaching a compromise with a loan shark business."
L23_1.m_Talk_ENG = L24_1
L24_1 = "因為管理局說和高利貸業者和解的話，對他們的形象不好。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "องค์การบริหารโลกแสดงความกังวลถึงวิสัยทัศน์เรื่องการประนีประนอมกับธุรกิจของเจ้าหนี้หน้าเลือดค่ะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Cục Quản Lý bày tỏ lo ngại về tiềm năng của việc đạt được thỏa hiệp với một doanh nghiệp cho vay nặng lãi."
L23_1.m_Talk_VTN = L24_1
L24_1 = "管理局觉得和高利贷进行妥协面子上比较难看。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Die Administration äußerte Bedenken hinsichtlich ihres Images, wenn sie einen Kompromiss mit einem Kredithai eingehen."
L23_1.m_Talk_DEU = L24_1
L24_1 = "L'Administration a émit des inquiétudes quant à l'optique de parvenir à un accord avec une entreprise de prêt d'argent."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "HORIZON_ACT6_EPILOGUE2@174#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3500611
L24_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "HORIZON_HORIZON_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "L"
L25_1 = "그래서 번듯한 얼굴이 필요해졌습니다."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "なので、堂々と表に出せる事業をする必要があります。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Hence this need for a more ostensibly legitimate front."
L24_1.m_Talk_ENG = L25_1
L25_1 = "所以需要長相端正的臉孔。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "เพราะเรื่องนี้จำเป็นต้องมีแนวหน้าที่ถูกกฎหมายอย่างชัดเจน"
L24_1.m_Talk_THA = L25_1
L25_1 = "Do đó, tôi cần một mặt tiền có vẻ chính đáng hơn."
L24_1.m_Talk_VTN = L25_1
L25_1 = "所以我需要体面一些的工作。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Daher diese Notwendigkeit einer scheinbar rechtschaffeneren Fassade."
L24_1.m_Talk_DEU = L25_1
L25_1 = "D'où ce besoin d'afficher un motif plus légitime."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
