L26_1 = "HORIZON_HORIZON_NULL_NULL"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "L"
L26_1 = "어떻습니까, 레이첼?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "どうですか、レイチェル？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "What do you think, Rachel?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "怎麼樣，瑞秋？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "คุณคิดว่ายังไงคะเรเชล?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Cô nghĩ sao, Rachel?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "怎么样，雷切尔？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Was denkst du darüber, Rachel?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Alors qu'en dites-vous, Rachel ?"
L25_1.m_Talk_FRA = L26_1
