L27_1 = "HORIZON_ACT6_EPILOGUE2@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3500611
L26_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_LAUGH"
L26_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L26_1.m_Pos = "R"
L26_1.m_Crash = 20
L27_1 = "그렇다면야 뭐! 독립자금 모으는 겸 열심히 해야지!"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "そういうことね！　独立資金を貯めるのを兼ねて頑張らなきゃだ！"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Well, in that case! I'd better work hard to save enough till I can move out!"
L26_1.m_Talk_ENG = L27_1
L27_1 = "你都這麼說了！我會一邊認真工作，一邊存獨立基金的！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "แหม ถ้างั้นนะ! ฉันนะทำงานให้หนักจะได้มีเงินเก็บพอก่อนย้ายออกล่ะ!"
L26_1.m_Talk_THA = L27_1
L27_1 = "Chà, trong trường hợp đó! Tốt hơn là chị nên làm việc chăm chỉ để tiết kiệm đủ cho đến khi chị có thể chuyển ra ngoài sống."
L26_1.m_Talk_VTN = L27_1
L27_1 = "如果是这样的话！为了能攒够独立资金，认真工作吧！雷切尔！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ach so! Okay, dann werde ich mich anstrengen! Auch dafür, um genug zu sparen, bis ich ausziehen kann!"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Eh bien, dans ce cas, je vais travailler dur pour mettre des sous de côté et pouvoir enfin déménager !"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
