L28_1 = "HORIZON_HORIZON_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "L"
L28_1 = "좋습니다. 입사를 환영합니다."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "いいでしょう。入社おめでとうございます。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Good. Welcome to the company."
L27_1.m_Talk_ENG = L28_1
L28_1 = "很好，歡迎你加入我們公司。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ดีค่ะ ยินดีต้อนรับสู่บริษัทของเรานะคะ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Tốt. Chào mừng cô đến với công ty."
L27_1.m_Talk_VTN = L28_1
L28_1 = "太好了。欢迎你入职。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Sehr gut. Herzlich willkommen in der Firma."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Parfait. Bienvenue à Horizon Finance."
L27_1.m_Talk_FRA = L28_1
