L31_1 = "그러면 환영식도 끝냈으니 사원 목록을 갱신해야겠군요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "それでは歓迎式も終わったので、社員リストを更新しなければなりませんね。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Now that the welcome party is over, I should update the staff roster."
L30_1.m_Talk_ENG = L31_1
L31_1 = "歡迎儀式結束了，來更新員工清冊吧。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เอาล่ะค่ะ ปาร์ตี้ต้อนรับจบแล้ว ฉันจะอัปเดตรายชื่อเจ้าหน้าที่นะคะ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Bây giờ tiệc chào mừng đã kết thúc, tôi nên cập nhật danh sách nhân viên."
L30_1.m_Talk_VTN = L31_1
L31_1 = "既然欢迎仪式结束，该更新职员目录了。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ende der Willkommensparty. Nun sollte ich die Personalliste aktualisieren."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Maintenant que la fête de bienvenue est terminée, je dois mettre à jour la liste du personnel."
L30_1.m_Talk_FRA = L31_1
