L34_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L35_1 = "어? 너……. 이 사진 어디서 가져 온 거야?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "え？　あんた……この写真どこから持ってきたの？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Huh? Hey… Where did you get this picture?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "嗯？你…… 這照片是從哪裡來的？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "หา? เฮ้... เธอไปเอารูปนี้มาจากไหนเนี่ย?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Huh? Này… Em lấy bức ảnh này ở đâu vậy?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "啊？你……这张照片是哪来的？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Hä? Hey ... Woher hast du dieses Bild?"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Hein ? Où... Où est-ce que tu as trouvé cette photo ?"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "HORIZON_ACT6_EPILOGUE2@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3500611
L35_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "HORIZON_HORIZON_NULL_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "지난번에 레이첼과 함께 보육원에서 묵을 때 입수했습니다."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "この前レイチェルと孤児院に泊まった時、入手したものです。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I acquired it during my temporary stay with you at the orphanage."
L35_1.m_Talk_ENG = L36_1
L36_1 = "這是上次和你一起去育幼院過夜時拿到的。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ได้มาตอนพักที่บ้านเด็กกำพร้าของคุณชั่วคราวน่ะค่ะ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Tôi đã có được nó trong thời gian ở tạm thời với cô tại trại trẻ mồ côi."
L35_1.m_Talk_VTN = L36_1
L36_1 = "上次和雷切尔一起留宿孤儿院的时候拿到的。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ich habe es während meines vorübergehenden Aufenthalts bei euch im Waisenhaus erworben."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Je l'ai acquise lors de mon séjour temporaire avec vous à l'orphelinat."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "HORIZON_ACT6_EPILOGUE2@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3500611
L36_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L37_1 = "야! 너 그거 완전 도둑질이잖아!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "えーそれって完全に窃盗じゃない！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Come on! That's stealing!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "喂！你這不是拿，是偷吧！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ไม่เอาดิ! แบบนั้นมันขโมยนะ!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Thôi nào! Đó là ăn cắp!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "喂！你这样完全就是在偷窃！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Hey! Das nennt man stehlen!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Hé ! C'est du vol !"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "HORIZON_ACT6_EPILOGUE2@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3500611
L37_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "HORIZON_HORIZON_NULL_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "괜찮습니다. 보육원장도 양심이 있으면 사진 한 장 뜯은 걸로 뭐라 하진 않겠죠."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "問題ありません。院長も良心があるなら、写真一枚なくなったことでとやかく言わないでしょう。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Don't worry. I'm sure the headmaster won't raise a fuss over a photo if he has any conscience."
L37_1.m_Talk_ENG = L38_1
L38_1 = "沒關係，育幼院長有良心的話，應該不會跟我計較區區一張照片吧？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ไม่ต้องห่วงหรอกค่ะ ฉันมั่นใจว่าครูใหญ่ไม่โวยวายกับแค่รูปใบเดียวหรอก ถ้าเขามีสติรู้คิดนะคะ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Đừng lo lắng. Tôi chắc rằng viện trưởng sẽ không làm ầm lên vì một bức ảnh nếu ông ta còn có lương tâm."
L37_1.m_Talk_VTN = L38_1
L38_1 = "没关系。如果孤儿院院长有良心的话，拿一张照片也不会生气的。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Mach dir keine Sorgen. Ich bin mir sicher, dass ein Foto den Heimleiter nicht jucken wird."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Pas d'inquiétude. Je doute que le directeur fasse toute une histoire pour une simple photo, si il a un minimum de conscience humaine."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "HORIZON_ACT6_EPILOGUE2@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3500611
L38_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L39_1 = "어휴, 진짜……."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "もう、まったく……"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Oh, jeez…"
L38_1.m_Talk_ENG = L39_1
L39_1 = "真是的……"
L38_1.m_Talk_TWN = L39_1
L39_1 = "โอย... หัวจะปวด"
L38_1.m_Talk_THA = L39_1
L39_1 = "Ôi, trời ơi…"
L38_1.m_Talk_VTN = L39_1
L39_1 = "哎呦，真是的……"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Puh, oh Mann ..."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Pfiou, sérieux..."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "HORIZON_ACT6_EPILOGUE2@189#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 189
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3500611
L39_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "HORIZON_HORIZON_NULL_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "불만 있습니까, 휴먼?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "文句がありますか、ヒューマン？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Something troubling you, human?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "有問題嗎，人類？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เป็นอะไรเหรอคะมนุษย์?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Có điều gì đó làm phiền cô sao, con người?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "你有不满吗，人类？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Hast du ein Problem, Mensch?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Vous avez une plainte à formuler, humaine ?"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "HORIZON_ACT6_EPILOGUE2@190#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 190
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3500611
L40_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L41_1 = "당연하지. 이렇게 붙여 두면 내가 꼭 굴러들어온 돌 같잖아."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "そりゃそうよ。この貼り方だと、アタシだけ浮いてるじゃない。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Well, yeah. This makes me look like the third, or I guess, fourth wheel now."
L40_1.m_Talk_ENG = L41_1
L41_1 = "當然！你這樣貼，搞得我的臉很突兀欸！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ก็ เอ้อ คือ นี่มันทำให้ฉันเหมือนมือที่สาม หรือน่าจะมือที่สี่เลยน่ะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "À. Bức ảnh này làm cho chị trông giống như bánh xe thứ ba, bánh xe thứ tư gì đó ấy."
L40_1.m_Talk_VTN = L41_1
L41_1 = "当然啦。如果你直接贴上去的话，一看我就是后来的。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Natürlich habe ich das. So hingepappt sehe ich aus wie das dritte Rad am Wagen."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Bien évidemment. On dirait que je suis une pièce rapportée si tu colles ma photo comme ça."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "HORIZON_ACT6_EPILOGUE2@191#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3500611
L41_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "HORIZON_HORIZON_NULL_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "과대평가는 좋지 않습니다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "自意識過剰は良くありません。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I would advise against such an overestimation of yourself for now."
L41_1.m_Talk_ENG = L42_1
L42_1 = "我不喜歡說話加油添醋。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ฉันขอแนะนำว่าตอนนี้อย่าเพิ่งประเมินตัวเองสูงไปนะคะ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tôi khuyên cô không nên đánh giá quá cao bản thân như vậy vào lúc này."
L41_1.m_Talk_VTN = L42_1
L42_1 = "对自己评价过高是不好的。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Von einer solchen Selbstüberschätzung würde ich vorerst abraten."
L41_1.m_Talk_DEU = L42_1
L42_1 = "J'éviterai d'émettre un jugement si favorable, si j'étais vous."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "HORIZON_ACT6_EPILOGUE2@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3500611
L42_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L43_1 = "어휴, 어떻게 된 애가 한마디도 안 져……."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "まったく、あんたって一言も負けないんだから……"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Ugh, you've got a comeback for everything, don't you…"
L42_1.m_Talk_ENG = L43_1
L43_1 = "真是的，每句話都要頂回來……"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ง่ะ เธอนี่ย้อนกันได้ทุกเรื่องเลยใช่มั้ยนะ..."
L42_1.m_Talk_THA = L43_1
L43_1 = "Ugh, em đã trở lại vì tất cả mọi thứ, phải không…"
L42_1.m_Talk_VTN = L43_1
L43_1 = "呼，你这人怎么一句话都不肯输……"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Urgh, du hast für alles eine flotte Antwort parat, was?"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Pff, tu as toujours quelque chose à redire, hein..."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "HORIZON_ACT6_EPILOGUE2@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3500611
L43_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L44_1 = "하지만 좋아. 그릴 얼굴이 하나 더 늘었으니까 분발해야겠네."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "いいよ！　描く顔がもう一つ増えたから頑張らないと！"
L43_1.m_Talk_JPN = L44_1
L44_1 = "But I guess it's okay. This just means I have to work harder to paint one more face in."
L43_1.m_Talk_ENG = L44_1
L44_1 = "不過我喜歡！現在又多一個人要畫，我要更努力囉！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "แต่ฉันว่าก็โอแหละ ฉันก็แค่ต้องทำงานหนักขึ้นเพราะต้องวาดลงไปอีกหน้าอะนะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Nhưng chị đoán là không sao. Điều này chỉ có nghĩa là chị phải làm việc chăm chỉ hơn để vẽ thêm một khuôn mặt nữa."
L43_1.m_Talk_VTN = L44_1
L44_1 = "很好，现在多了一张要画的脸，所以要更加卖力了。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Aber okay. Das bedeutet nur, dass ich ein weiteres Gesicht malen muss."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Mais ça me convient. Il ne me reste plus qu'à travailler dur pour peindre une visage de plus."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "HORIZON_ACT6_EPILOGUE2@194#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 194
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3500611
L44_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "HORIZON_HORIZON_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "무슨 말씀이십니까, 휴먼."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "どういう意味ですか、ヒューマン。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "What do you mean, human?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "你在說什麼，人類？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "หมายความว่ายังไงคะมนุษย์?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Ý cô là gì thế, con người?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "你在说什么，人类。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Wovon redest du, Mensch?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Que voulez-vous dire, humaine ?"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "HORIZON_ACT6_EPILOGUE2@195#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 195
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3500611
L45_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L46_1 = "네 아르바이트 첫날. 선물 아직 못 줬잖아."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "あんたのアルバイト初日のお祝い。プレゼントをまだ渡してないでしょ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Remember that first day you worked part time? I haven't given your gift yet."
L45_1.m_Talk_ENG = L46_1
L46_1 = "你第一天打工的禮物我都還沒送你呢！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "จำวันแรกที่เธอทำพาร์ทไทม์ได้มั้ยล่ะ? ฉันยังไม่ได้ให้ของขวัญเธอเลยนะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Có nhớ ngày đầu tiên em làm việc bán thời gian không? Chị vẫn chưa tặng quà cho em."
L45_1.m_Talk_VTN = L46_1
L46_1 = "你去兼职的第一天，我不是没给你礼物吗。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Erinnerst du dich an den ersten Tag bei deinem Job? Ich muss dir noch dein Geschenk geben."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Tu te souviens du jour où tu as commencé ton petit boulot ? Je ne t'ai toujours pas donné ton cadeau."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "HORIZON_ACT6_EPILOGUE2@196#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 196
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3500611
L46_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L47_1 = "내가 부를 때까지 여기서 나오면 안 돼, 알았지?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "アタシが呼ぶまでここから出ちゃダメだよ。わかった？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Don't come outside till I call for you, okay?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "在我叫你之前，不可以離開這裡喔！知道嗎？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "อย่าออกมาจนกว่าฉันจะเรียกนะ โอเค้?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Đừng ra ngoài cho đến khi chị gọi nhé?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "在我喊你之前，不可以从这里出来，知道了吗？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Komm nicht raus, bis ich nach dir rufe, okay?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Ne sors pas tant que je ne t'ai pas appelée, d'accord ?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "HORIZON_ACT6_EPILOGUE2@197#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 197
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3500611
L47_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "HORIZON_HORIZON_NULL_NULL"
L47_1.m_CharStrID = L48_1
L48_1 = "사무실 벽에 낙서하면 경범죄로 신고하겠습니다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "事務室の壁に落書きしたら軽犯罪で通報します。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "I will press charges against you if you're thinking of defacing the office walls."
L47_1.m_Talk_ENG = L48_1
L48_1 = "你敢在辦公室牆上亂塗鴉的話，我會報警抓你。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ถ้าคิดจะทำผนังออฟฟิศมีตำหนิฉันจะคิดค่าปรับนะคะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tôi sẽ tính phí phạt nếu cô đang nghĩ đến việc phá hoại các bức tường văn phòng đấy."
L47_1.m_Talk_VTN = L48_1
L48_1 = "如果你在办公室的墙上涂鸦，我会举报你轻度犯罪。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Ich werde Anzeige erstatten, wenn du die Bürowände verunstaltest."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Sachez que je porterai plainte si votre plan est de dégrader la façade de mon bureau."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "HORIZON_ACT6_EPILOGUE2@198#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 198
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3500611
L48_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L49_1 = "낙서라니! 세상 사람들이 다 알 작품이 될 거라고!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "落書きだって！？　これは将来世界中の人に知れ渡る作品になるんだよ！？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Defacing?! Come on, this is going to become a masterpiece!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "什麼亂塗鴉！這將成為世界名作好嗎！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "มีตำหนิเหรอ?! เดี๋ยวเถอะ นี่มันต้องเป็นผลงานชิ้นเอกต่างหาก!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Phá hoại?! Thôi nào, đây sẽ trở thành một kiệt tác!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "怎么能说是涂鸦呢！这会成为全世界的人们都认可的作品！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Verunstalten doch nicht! Das wird ein stadtbekanntes Kunstwerk."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Dégrader ?! N'importe quoi ! Tu vas voir, ça sera un chef d'œuvre !"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "HORIZON_ACT6_EPILOGUE2@199#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 199
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3500611
L49_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "HORIZON_HORIZON_NULL_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "그럼 저도 감독해야겠습니다. 당신이라면 절 실제보다 과하게 어린 모습으로 그릴 테니까요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "それだと私が監修する必要があります。あなたなら私を実際より過度に幼い姿で描きますからね。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Then I must stay and supervise. Otherwise, I am certain you will paint me to appear far younger than I actually look."
L49_1.m_Talk_ENG = L50_1
L50_1 = "那我必須監工。因為你會把我畫得比實際還年輕很多！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ถ้าอย่างนั้นฉันก็ต้องคอยดูแลค่ะ ไม่อย่างนั้น ฉันแน่ใจเลยว่าคุณต้องวาดฉันออกมาเด็กกว่าที่เป็นจริงๆ มากแน่"
L49_1.m_Talk_THA = L50_1
L50_1 = "Vậy thì tôi phải ở lại và giám sát. Nếu không, tôi chắc chắn cô sẽ vẽ tôi trông nhỏ tuổi hơn nhiều so với vẻ ngoài của tôi."
L49_1.m_Talk_VTN = L50_1
L50_1 = "那就更要监督你了。以防某位职员做出什么出格的举动。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Dann sollte ich bleiben und dich beaufsichtigen. Denn sonst wirst du mich viel jünger darstellen, als ich tatsächlich aussehe."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Dans ce cas, je me dois de rester afin de superviser votre travail. Je crains que vous ne dépeignez une image de moi bien plus jeune que dans la réalité."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "HORIZON_ACT6_EPILOGUE2@200#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 200
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3500611
L50_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L51_1 = "아차. 젖병 물려 주려고 했는데 들켰네."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "あちゃー哺乳瓶を持たせようとしたの、バレちゃったか。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Oops. You got me. I was going to stick a pacifier in your mouth."
L50_1.m_Talk_ENG = L51_1
L51_1 = "哎呀！被抓包，本來想替你畫個奶瓶的～"
L50_1.m_Talk_TWN = L51_1
L51_1 = "อุ่ย ฉันละเกลียดเด็กหัวไวอย่างเธอชะมัดเลย ต้องเอาจุกนมยัดปากละมั้งเนี่ย"
L50_1.m_Talk_THA = L51_1
L51_1 = "Ối. Thôi được. Chị đã định bịt miệng em rồi."
L50_1.m_Talk_VTN = L51_1
L51_1 = "哎呀，本来想给你画个奶嘴的，被发现了。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Hoppla. Du hast mich erwischt. Ich wollte dir einen Schnuller in den Mund malen."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Oups, tu m'as eue. Je voulais te peindre avec une tétine dans la bouche."
L50_1.m_Talk_FRA = L51_1
