L2_1 = "HORIZON_ACT6_EPILOGUE2@201#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 201
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 3500611
L1_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L2_1 = "그런데 호라이즌, 관리국 사람들이랑 얘기했으면 혹시 그 작전 얘기 들었어? 빌딩에서 벌어졌다던?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "ていうかホライズン、管理局の人と話してるならあの作戦の話は聞いた？　ビルで起きたっていう。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "By the way, Horizon. If you've been talking with the Administration, have you heard about that one operation? You know, the one at a building?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "不過，地平線，你有和管理局談過的話，那你有聽說那個作戰的事嗎？聽說發生在大樓裡欸？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ว่าแต่ว่านะฮอไรซัน ถ้าเธอคุยกับองค์การบริหารโลกมา เธอรู้เรื่องปฏิบัติการหนึ่งมั้ย? อันที่ตึกนั้นน่ะ?"
L1_1.m_Talk_THA = L2_1
L2_1 = "Nhân tiện, Horizon. Nếu đã nói chuyện với Cục Quản Lý, em đã nghe nói về một hoạt động đó chưa? Cô biết đấy, hoạt động ở một tòa nhà ấy?"
L1_1.m_Talk_VTN = L2_1
L2_1 = "可是地平线，如果你和管理局的人有合作的话，听说过那个作战吗？在建筑物里发生的？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Übrigens, Horizon. Hast du von dieser einen Operation gehört, als du mit der Administration gesprochen hast? Die, die in einem Gebäude stattgefunden habe?"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Au fait, Horizon. Si tu as pu discuter avec les gens de l'Administration, as-tu entendu parler de cette fameuse opération ? Celle qui a eu lieu dans un certain bâtiment ?"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "HORIZON_ACT6_EPILOGUE2@202#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 202
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 3500611
L2_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "HORIZON_HORIZON_NULL_NULL"
L2_1.m_CharStrID = L3_1
L3_1 = "섬멸 작전 말씀이십니까. 일단은 저도 한 몫 거들었습니다."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "殲滅作戦ですか。一応私も活躍しています。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "You must mean the elimination operation. I suppose you could say I had a hand in that."
L2_1.m_Talk_ENG = L3_1
L3_1 = "你是指殲滅戰嗎？總之我也有參一腳。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "คุณคงหมายถึงปฏิบัติการถอนรากถอนโคนสินะคะ ท่าทางคุณคงจะบอกว่าฉันมีส่วนด้วย"
L2_1.m_Talk_THA = L3_1
L3_1 = "Ý cô là hoạt động tiêu diệt ấy à. Tôi cho rằng cô có thể nói là tôi đã tham gia vào đó."
L2_1.m_Talk_VTN = L3_1
L3_1 = "是说歼灭作战吗。我也出了一些力呢。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Du meinst wohl die Eliminierungsoperation. Man könnte sagen, dass ich daran beteiligt war."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Vous devez faire référence à l'opération Élimination. Je suppose que l'on peut dire que j'y ai joué un certain rôle."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "HORIZON_ACT6_EPILOGUE2@203#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 203
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3500611
L3_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "RACHEL_NPC_NULL_NULL"
L4_1 = "그래! 바로 그거야! 내 불안감을 날려 버리려면 그런 화끈한 얘기가 필요해!"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "そう！　まさにそれ！　私の不安感を吹き飛ばすには、そういうスリリングな話が必要なの！"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Nice! That's what I'm talking about! That's exactly the sort of kick-ass story I need to keep my anxiety away!"
L3_1.m_Talk_ENG = L4_1
L4_1 = "沒錯！就是那個！要消除我的不安的話，就需要這種大快人心的事情！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แม่นเด้อ! ฉันหมายถึงอันนั้นแหละ! เรื่องนั้นปังจริงอะไรจริงจนฉันต้องทำเป็นไม่กังวลเลย!"
L3_1.m_Talk_THA = L4_1
L4_1 = "Tốt! Đó là những gì chị đang nói đấy! Đó chính xác là loại câu chuyện đáng kinh ngạc mà chị cần để xóa tan sự lo lắng của mình!"
L3_1.m_Talk_VTN = L4_1
L4_1 = "对！我说的就是这个！快和我聊聊吧，我现在紧张死了，就需要这种火爆的话题缓解一下！"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Aha! Super! Das ist genau die spannende Geschichte, die ich brauche, um meine Angst abzuschütteln!"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Génial ! C'est exactement le genre d'histoires trop cool dont j'ai besoin pour éviter les crises d'angoisse !"
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "HORIZON_ACT6_EPILOGUE2@204#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 204
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3500611
L4_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "HORIZON_HORIZON_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "……작업하는 동안 말씀드리겠습니다. 오디오가 비면 지루해질 테니까요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "……作業中に話すとしましょう。オーディオがないと退屈してしまうでしょうから。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "…Then I shall tell you all about it while you work. A lengthy silence could get awfully boring, after all."
L4_1.m_Talk_ENG = L5_1
L5_1 = "……工作中跟你說一下，沒有音響會很無聊。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "... ถ้าอย่างนั้นฉันจะเล่าให้ฟังระหว่างที่คุณทำงานนะคะ ยังไงต้องนั่งเงียบนานๆ คงน่าเบื่อแย่"
L4_1.m_Talk_THA = L5_1
L5_1 = "… Vậy thì tôi sẽ kể cho cô nghe tất cả về điều đó trong khi cô làm việc. Dù sao thì sự im lặng kéo dài sẽ trở nên vô cùng nhàm chán."
L4_1.m_Talk_VTN = L5_1
L5_1 = "……那个等工作的时候再说吧。毕竟工作的时候太安静了，应该会很无聊。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Dann erzähle ich dir alles, während du arbeitest. Eine längere Stille könnte schließlich langweilig werden."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Dans ce cas je pourrais vous la raconter pendant que vous réaliserez votre œuvre. Je crois que nous aurons besoin de ce fond sonore pour éviter l'ennui."
L4_1.m_Talk_FRA = L5_1
