L8_1 = "HORIZON_ACT6_EPILOGUE2@207#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 207
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3500611
L7_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "리타. 대시. 이제 저는 당신들이 없는 시간을 준비하려고 합니다."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "リタ、ダッシュ。私はあなたたちのいない時を迎えようとしています。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Rita. Dash. I am now preparing for a period without you two."
L7_1.m_Talk_ENG = L8_1
L8_1 = "麗塔、黛西，我現在要習慣沒有你們的時間。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ริตา แดช ตอนนี้ฉันกำลังเตรียมตัวสำหรับช่วงเวลาที่ไม่มีเธอสองคนแล้วนะ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Rita. Dash. Bây giờ tôi đang chuẩn bị cho một thời kỳ mà không có hai người."
L7_1.m_Talk_VTN = L8_1
L8_1 = "丽塔。黛西。现在我要准备适应你们不在的时间了。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Rita. Dash. Ich bereite mich jetzt auf eine Zeit ohne euch zwei vor."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Rita. Dash. Je dois maintenant me préparer à passer une période sans vous avoir à mes côtés."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "HORIZON_ACT6_EPILOGUE2@208#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 208
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3500611
L8_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "얼마나 긴 시간이 될지 모르겠지만, 당신들에게서 배운 대로 시도해 보려고 합니다."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "どれほど長い時間になるかわかりませんが、あなたたちから教わったとおりに試してみようと思います。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I do not know how long this period will last, but I will endeavor to do as you have taught me."
L8_1.m_Talk_ENG = L9_1
L9_1 = "雖然不知道要花多長的時間，但我會照你們教我的去試試看。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ฉันไม่รู้หรอกว่าช่วงเวลานี้จะยาวนานแค่ไหน แต่ฉันจะตั้งใจทำมันให้ดีอย่างที่พวกเธอเคยสอนไว้"
L8_1.m_Talk_THA = L9_1
L9_1 = "Tôi không biết khoảng thời gian này sẽ kéo dài bao lâu, nhưng tôi sẽ cố gắng làm theo những gì các cô đã dạy tôi."
L8_1.m_Talk_VTN = L9_1
L9_1 = "虽然不知道要耗时多久，但我会按照从你们那学到的方法去尝试。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ich weiß nicht, wie lange das dauern wird, aber ich werde mich bemühen, das zu tun, was ihr mir beigebracht habt."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Je ne sais pas combien de temps cela durera, mais je ferait tout mon possible pour suivre vos enseignements."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "HORIZON_ACT6_EPILOGUE2@209#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 209
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3500611
L9_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "실패도, 실수도 겪을 수 있습니다. 저는 결함품이니 당신들만큼 잘하지 못하겠죠. "
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "失敗もミスもあるでしょう。私は欠陥品ですから、あなたたちほど上手くやっていけないかもしれません。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "I may fail or make mistakes. Being the defective program that I am, I may never excel at this as much as you. "
L9_1.m_Talk_ENG = L10_1
L10_1 = "很有可能會經歷失敗或錯誤，誰叫我是瑕疵品，沒辦法像你們那麼棒。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ฉันอาจล้มเหลวหรือทำผิดทำพลาด ก็นะ โปรแกรมที่มีข้อบกพร่องอย่างฉันคงไม่มีวันเป็นเลิศในเรื่องนี้ได้อย่างพวกเธอหรอก "
L9_1.m_Talk_THA = L10_1
L10_1 = "Tôi có thể thất bại hoặc mắc sai lầm. Tôi là một chương trình khiếm khuyết, tôi có thể không bao giờ xuất sắc về mặt này như hai người."
L9_1.m_Talk_VTN = L10_1
L10_1 = "这期间可能会经历失败或失误。毕竟我是残次品，所以没办法做得像你们那样好。 "
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ich werde womöglich scheitern und Fehler machen. Da ich eine Mangelware bin, werde ich vielleicht nie so gut sein wie ihr."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Je vais certainement faire des erreurs et échouer. Étant le programme défectueux que je suis, je ne serai jamais aussi douée que vous. "
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "HORIZON_ACT6_EPILOGUE2@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 3500611
L10_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "그러니 앞으로, 두 번 다시 울지 않게."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ですから、これからは二度と泣かないように。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "So lest there be any further cause for weeping…"
L10_1.m_Talk_ENG = L11_1
L11_1 = "以後我們都不再哭泣，"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เกรงว่าจะมีเหตุให้ร้องไห้เพิ่มเสียแล้ว..."
L10_1.m_Talk_THA = L11_1
L11_1 = "Vì vậy, để không còn có thêm nguyên nhân nào nữa cho việc khóc lóc…"
L10_1.m_Talk_VTN = L11_1
L11_1 = "所以以后，别让我再次哭泣。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Also, damit es nie wieder einen Grund zum Weinen gibt ..."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Mais je vais faire en sorte de ne plus jamais avoir de raison de pleurer."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "HORIZON_ACT6_EPILOGUE2@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 3500611
L11_1.m_CutScenStrID = "HORIZON_ACT6_EPILOGUE2"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "눈물 요정아. 달아나라. 뚝."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "涙の妖精よ、飛んでけ。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Go away, tear fairy. Shoo."
L11_1.m_Talk_ENG = L12_1
L12_1 = "眼淚仙子，快快走。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ไปให้พ้นนะเจ้าน้ำตา! ชิ่วๆ!"
L11_1.m_Talk_THA = L12_1
L12_1 = "Cút đi, đồ xúi quẩy. Đi đi."
L11_1.m_Talk_VTN = L12_1
L12_1 = "眼泪啊，离我远点！停！"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Geh weg, Tränenfee. Geh."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Allez-vous-en, vilaines larmes ! Du balai !"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
